COURSE.add({
  id: 'm07', order: 7, icon: '🚀',
  title: { en: 'AgentCore Runtime: deploy and run your agent', he: 'AgentCore Runtime: עושים deploy לסוכן ומריצים אותו' },
  summary: { en: 'Sessions and microVMs, the agent contract, the AgentCore CLI, invoking from an app, auth, networking, pricing, quotas and debugging.', he: 'Sessions ו-microVMs, החוזה של הסוכן, ה-AgentCore CLI, קריאה מאפליקציה, auth, רשת, תמחור, quotas ודיבוג.' },
  glossary: [
    { term: 'AgentCore Runtime', aka: ['Runtime', 'agent runtime'], en: 'The AWS service that hosts your agent code as a serverless service. One deployed agent application is called an "agent runtime".', he: 'שירות AWS שמארח את קוד הסוכן שלך כשירות serverless. אפליקציית סוכן אחת שעשו לה deploy נקראת "agent runtime".' },
    { term: 'Session', aka: ['runtime session', 'runtimeSessionId', 'sessions'], en: 'One conversation with the agent, identified by `runtimeSessionId`. Each session runs in its own microVM.', he: 'שיחה אחת עם הסוכן, שמזוהה לפי `runtimeSessionId`. כל session רץ ב-microVM משלו.' },
    { term: 'microVM', aka: ['microVMs'], en: 'A very small, isolated virtual machine. Runtime gives one to each session and destroys it when the session ends.', he: 'מכונה וירטואלית קטנה מאוד ומבודדת. Runtime נותן אחת לכל session ומשמיד אותה כשה-session נגמר.' },
    { term: 'Session isolation', en: 'No CPU, memory or files are shared between two sessions. One user can never see data of another user.', he: 'שני sessions לא חולקים CPU, זיכרון או קבצים. משתמש אחד לא יכול לראות מידע של משתמש אחר.' },
    { term: 'Idle timeout', aka: ['idleRuntimeSessionTimeout'], en: 'How long a session may sit with no activity before Runtime terminates it. 15 minutes by default.', he: 'כמה זמן session יכול לשבת בלי פעילות לפני ש-Runtime מסיים אותו. 15 דקות כברירת מחדל.' },
    { term: 'Max lifetime', aka: ['maxLifetime'], en: 'The hard limit on how long one session can live, even if it is busy. 8 hours on microVMs.', he: 'הגבול הקשיח על כמה זמן session אחד יכול לחיות, גם אם הוא עסוק. 8 שעות על microVMs.' },
    { term: 'Cold start', aka: ['cold starts'], en: 'The extra wait on the first request of a new session, while the environment starts and your code loads.', he: 'ההמתנה הנוספת בבקשה הראשונה של session חדש, בזמן שהסביבה עולה והקוד שלך נטען.' },
    { term: 'Service contract', aka: ['agent contract', 'contract'], en: 'The rules your code must follow so that Runtime can talk to it: which port, which paths, which CPU architecture.', he: 'הכללים שהקוד שלך חייב לקיים כדי ש-Runtime יוכל לדבר איתו: איזה פורט, אילו נתיבים, איזו ארכיטקטורת CPU.' },
    { term: 'Entrypoint', aka: ['@app.entrypoint'], en: 'The function marked with `@app.entrypoint`. Runtime calls it for every request to `/invocations`.', he: 'הפונקציה שסומנה ב-`@app.entrypoint`. Runtime קורא לה בכל בקשה ל-`/invocations`.' },
    { term: 'BedrockAgentCoreApp', en: 'The class in the AgentCore Python SDK that wraps your function in the HTTP server that Runtime expects.', he: 'המחלקה ב-AgentCore Python SDK שעוטפת את הפונקציה שלך בשרת ה-HTTP ש-Runtime מצפה לו.' },
    { term: 'HealthyBusy', en: 'A `/ping` answer that means "I am still working in the background, do not terminate me as idle".', he: 'תשובה של `/ping` שאומרת "אני עדיין עובד ברקע, אל תסיים אותי כ-idle".' },
    { term: 'ARM64', aka: ['linux/arm64'], en: 'A CPU architecture. Runtime runs only ARM64 code, so container images must be built for `linux/arm64`.', he: 'ארכיטקטורת CPU. Runtime מריץ רק קוד ARM64, ולכן container images חייבים להיבנות ל-`linux/arm64`.' },
    { term: 'Direct code deployment', aka: ['CodeZip', 'direct code deploy'], en: 'Deploying a ZIP of your code and dependencies instead of a container image. No Docker needed.', he: 'deploy של קובץ ZIP עם הקוד והתלויות שלך במקום container image. לא צריך Docker.' },
    { term: 'Container image', aka: ['container', 'image'], en: 'A package with your code and everything it needs to run. For Runtime it is stored in Amazon ECR, the AWS image registry.', he: 'חבילה עם הקוד שלך וכל מה שהוא צריך כדי לרוץ. בשביל Runtime היא נשמרת ב-Amazon ECR, ה-registry של AWS ל-images.' },
    { term: 'SSE', aka: ['Server-Sent Events', 'text/event-stream'], en: 'Server-Sent Events. A simple way to stream a response over HTTP as a series of `data:` lines.', he: 'Server-Sent Events. דרך פשוטה להזרים תשובה ב-HTTP כסדרה של שורות `data:`.' },
    { term: 'MCP', aka: ['Model Context Protocol'], en: 'Model Context Protocol. An open standard for how an agent finds and calls tools on a tool server.', he: 'Model Context Protocol. תקן פתוח שקובע איך סוכן מוצא כלים בשרת כלים וקורא להם.' },
    { term: 'A2A', aka: ['Agent-to-Agent'], en: 'Agent-to-Agent protocol. An open standard for agents to call each other as separate services.', he: 'פרוטוקול Agent-to-Agent. תקן פתוח שמאפשר לסוכנים לקרוא זה לזה כשירותים נפרדים.' },
    { term: 'AgentCore CLI', aka: ['agentcore'], en: 'The command-line tool `agentcore` (installed with npm) that creates, tests, deploys and inspects AgentCore projects.', he: 'כלי שורת הפקודה `agentcore` (מותקן עם npm) שיוצר, בודק, עושה deploy ובוחן פרויקטים של AgentCore.' },
    { term: 'agentcore.json', en: 'The project file that lists what the AgentCore CLI should deploy: runtimes, harnesses, memory, gateways, credentials.', he: 'קובץ הפרויקט שמפרט מה ה-AgentCore CLI צריך לפרוס: runtimes, harnesses, memory, gateways, credentials.' },
    { term: 'Starter toolkit', aka: ['bedrock-agentcore-starter-toolkit'], en: 'The older Python command-line tool for AgentCore (`agentcore configure`, `agentcore launch`). Deprecated: do not use it.', he: 'כלי שורת הפקודה הישן ב-Python ל-AgentCore (`agentcore configure`, `agentcore launch`). הוצא משימוש: לא להשתמש בו.' },
    { term: 'Control plane', en: 'The APIs that create and configure resources. For AgentCore: the `bedrock-agentcore-control` client.', he: 'ה-APIs שיוצרים ומגדירים משאבים. ב-AgentCore: ה-client בשם `bedrock-agentcore-control`.' },
    { term: 'Data plane', en: 'The APIs you call at run time, for example to invoke the agent. For AgentCore: the `bedrock-agentcore` client.', he: 'ה-APIs שקוראים להם בזמן ריצה, למשל כדי להפעיל את הסוכן. ב-AgentCore: ה-client בשם `bedrock-agentcore`.' },
    { term: 'Version', aka: ['runtime version', 'versions'], en: 'A snapshot of the configuration of a runtime that never changes. Every update creates a new version.', he: 'snapshot של הקונפיגורציה של runtime שלא משתנה לעולם. כל עדכון יוצר version חדש.' },
    { term: 'Endpoint', aka: ['DEFAULT endpoint', 'endpoints'], en: 'A named pointer to one version of a runtime. The `DEFAULT` endpoint always follows the newest version.', he: 'מצביע עם שם אל version אחד של runtime. ה-endpoint בשם `DEFAULT` תמיד עוקב אחרי ה-version החדש ביותר.' },
    { term: 'Qualifier', en: 'The endpoint name that you pass when you invoke the agent, for example `qualifier="prod"`.', he: 'שם ה-endpoint שמעבירים כשמפעילים את הסוכן, לדוגמה `qualifier="prod"`.' },
    { term: 'Inbound auth', aka: ['inbound authentication'], en: 'The check of who is allowed to call your agent. On Runtime: IAM SigV4 or a JWT.', he: 'הבדיקה של מי רשאי לקרוא לסוכן שלך. ב-Runtime: IAM SigV4 או JWT.' },
    { term: 'SigV4', aka: ['IAM SigV4', 'Signature Version 4'], en: 'The standard AWS way to sign a request with IAM credentials. The AWS SDKs do it for you.', he: 'הדרך הסטנדרטית של AWS לחתום על בקשה עם IAM credentials. ה-SDKs של AWS עושים את זה בשבילך.' },
    { term: 'JWT', aka: ['bearer token', 'JSON Web Token'], en: 'A signed token from an identity provider that proves who the user is. It is sent in the `Authorization: Bearer` header.', he: 'טוקן חתום מספק זהויות שמוכיח מי המשתמש. הוא נשלח ב-header בשם `Authorization: Bearer`.' },
    { term: 'Execution role', en: 'The IAM role that the runtime itself uses to call other AWS services, for example Bedrock models. Not the role of the caller.', he: 'ה-IAM role שה-runtime עצמו משתמש בו כדי לקרוא לשירותי AWS אחרים, למשל מודלים ב-Bedrock. לא ה-role של הקורא.' },
    { term: 'VPC', aka: ['Virtual Private Cloud'], en: 'Your private network inside AWS. Putting the agent in a VPC lets it reach private resources such as an internal database.', he: 'הרשת הפרטית שלך בתוך AWS. כששמים את הסוכן ב-VPC, הוא יכול להגיע למשאבים פרטיים כמו מסד נתונים פנימי.' },
    { term: 'Platform version', aka: ['platformVersion', 'V1', 'V2'], en: 'How Runtime starts your agent. V1 is the default. V2 starts sessions from a saved snapshot of your initialized environment.', he: 'איך Runtime מעלה את הסוכן שלך. V1 הוא ברירת המחדל. V2 מעלה sessions מתוך snapshot שמור של הסביבה המאותחלת שלך.' },
    { term: 'Instances', aka: ['Instances compute type'], en: 'A Runtime compute type that uses managed EC2 machines in your account instead of microVMs: GPUs and sessions up to 14 days.', he: 'סוג compute של Runtime שמשתמש במכונות EC2 מנוהלות בחשבון שלך במקום ב-microVMs: GPUs ו-sessions של עד 14 ימים.' },
    { term: 'Throttling', aka: ['ThrottlingException', '429'], en: 'When AWS rejects requests because you send more per second than your quota allows. The error is HTTP 429.', he: 'כש-AWS דוחה בקשות כי אתה שולח יותר בשנייה ממה שה-quota שלך מאפשר. השגיאה היא HTTP 429.' }
  ],
  lessons: [
    {
      id: 'm07l1', minutes: 12,
      title: { en: 'What Runtime is, and the session lifecycle', he: 'מה זה Runtime, ומחזור החיים של session' },
      blocks: [
        { t: 'p', en: 'Your agent works on your laptop. One user, one process, your own credentials. Production is a different world, and an agent is a strange kind of workload. Look at what makes it hard to host:', he: 'הסוכן שלך עובד על הלפטופ. משתמש אחד, תהליך אחד, ה-credentials שלך. פרודקשן הוא עולם אחר, וסוכן הוא סוג מוזר של עומס עבודה. הנה מה שמקשה לארח אותו:' },
        { t: 'table', head: { en: ['The problem', 'What AgentCore Runtime does'], he: ['הבעיה', 'מה AgentCore Runtime עושה'] }, rows: {
          en: [['Many users at once. Their data, files and tokens must never mix.', 'Every [[Session]] gets its own [[microVM]] with isolated CPU, memory and file system.'], ['Load goes from zero to thousands of conversations and back.', '[[Serverless]]: it scales by itself. There are no servers for you to manage.'], ['Some tasks take minutes or hours, not milliseconds.', 'A request can run 15 minutes, a stream 60 minutes, background work up to 8 hours.'], ['An agent mostly **waits**: for the model, for tools.', 'You pay for the CPU you actually use, not for the waiting time.'], ['Someone must check who may call the agent.', 'Built-in [[Inbound auth]]: IAM or a JWT, checked before your code runs.']],
          he: [['הרבה משתמשים בו-זמנית. המידע, הקבצים והטוקנים שלהם אסור שיתערבבו.', 'כל [[Session]] מקבל [[microVM]] משלו עם CPU, זיכרון ומערכת קבצים מבודדים.'], ['העומס עולה מאפס לאלפי שיחות וחוזר.', '[[Serverless]]: עושה scaling לבד. אין שרתים שאתה צריך לנהל.'], ['חלק מהמשימות לוקחות דקות או שעות, לא אלפיות שנייה.', 'בקשה יכולה לרוץ 15 דקות, stream 60 דקות, עבודת רקע עד 8 שעות.'], ['סוכן בעיקר **מחכה**: למודל, לכלים.', 'משלמים על ה-CPU שבאמת משתמשים בו, לא על זמן ההמתנה.'], ['מישהו צריך לבדוק מי רשאי לקרוא לסוכן.', '[[Inbound auth]] מובנה: IAM או JWT, נבדק לפני שהקוד שלך רץ.']] } },
        { t: 'note', kind: 'jargon', en: '[[AgentCore Runtime]] in one sentence: it runs your agent code (any framework, any model) as a serverless service where **every session gets its own microVM**. One deployed agent is called an **agent runtime**.', he: '[[AgentCore Runtime]] במשפט אחד: הוא מריץ את קוד הסוכן שלך (כל framework, כל מודל) כשירות serverless שבו **כל session מקבל microVM משלו**. סוכן אחד שעשו לו deploy נקרא **agent runtime**.' },
        { t: 'h', en: 'Why a microVM per session?', he: 'למה microVM לכל session?' },
        { t: 'p', en: 'A normal web server handles all users in one process. That is fine when the code is fixed. But an agent holds a whole conversation in memory, writes files, keeps access tokens of the user, and sometimes runs code that **a model wrote**. If two users share a process, one bug or one [[Session isolation|isolation]] mistake can leak the data of one user to another. Runtime removes that whole class of bugs: nothing is shared. When a session ends, its microVM is destroyed and its memory is wiped.', he: 'שרת web רגיל מטפל בכל המשתמשים בתהליך אחד. זה בסדר כשהקוד קבוע. אבל סוכן מחזיק שיחה שלמה בזיכרון, כותב קבצים, שומר access tokens של המשתמש, ולפעמים מריץ קוד ש**מודל כתב**. אם שני משתמשים חולקים תהליך, באג אחד או טעות [[Session isolation|בידוד]] אחת יכולים להדליף מידע של משתמש אחד לאחר. Runtime מבטל את כל סוג הבאגים הזה: שום דבר לא משותף. כש-session נגמר, ה-microVM שלו מושמד והזיכרון שלו נמחק.' },
        { t: 'quiz', q: { en: 'Which statements about session isolation on Runtime are true? Pick all that apply.', he: 'אילו משפטים על session isolation ב-Runtime נכונים? בחר את כל הנכונים.' },
          options: { en: ['Each session runs in its own microVM with its own CPU, memory and file system', 'After a session is terminated, its microVM is destroyed and its memory is wiped', 'If you use the same session ID a day later, you get the old files and variables back', 'Two sessions never share files'], he: ['כל session רץ ב-microVM משלו עם CPU, זיכרון ומערכת קבצים משלו', 'אחרי ש-session מסתיים, ה-microVM שלו מושמד והזיכרון שלו נמחק', 'אם משתמשים באותו session ID יום אחר כך, מקבלים בחזרה את הקבצים והמשתנים הישנים', 'שני sessions אף פעם לא חולקים קבצים'] },
          answer: [0, 1, 3], explain: { en: 'After termination, the same ID gets a **fresh** environment. Session state is ephemeral. Anything that must survive goes to AgentCore Memory or to your own storage.', he: 'אחרי סיום, אותו ID מקבל סביבה **חדשה**. ה-state של session הוא זמני. כל מה שחייב לשרוד הולך ל-AgentCore Memory או לאחסון משלך.' } },
        { t: 'h', en: 'The life of a session', he: 'החיים של session' },
        { t: 'p', en: 'A session has three states: **Active** (handling a request or doing background work), **Idle** (alive, waiting for the next request) and **Terminated**. Your app chooses the session ID. The first request with a new ID creates the microVM. Later requests with the same ID go to the same microVM, so your agent object and its message history are still in memory.', he: 'ל-session יש שלושה מצבים: **Active** (מטפל בבקשה או עושה עבודת רקע), **Idle** (חי, מחכה לבקשה הבאה) ו-**Terminated**. האפליקציה שלך בוחרת את ה-session ID. הבקשה הראשונה עם ID חדש יוצרת את ה-microVM. בקשות מאוחרות יותר עם אותו ID מגיעות לאותו microVM, ולכן אובייקט הסוכן והיסטוריית ההודעות שלו עדיין בזיכרון.' },
        { t: 'flow', steps: { en: ['First request with a new session ID', 'Runtime creates a microVM', 'Active: your code handles the request', 'Idle: waits for the next request', '15 idle minutes, or 8 hours in total', 'Terminated: microVM destroyed'], he: ['בקשה ראשונה עם session ID חדש', 'Runtime יוצר microVM', 'Active: הקוד שלך מטפל בבקשה', 'Idle: מחכה לבקשה הבאה', '15 דקות idle, או 8 שעות בסך הכול', 'Terminated: ה-microVM מושמד'] } },
        { t: 'table', head: { en: ['Number', 'Value', 'What it means for you'], he: ['מספר', 'ערך', 'מה זה אומר בשבילך'] }, rows: {
          en: [['[[Idle timeout]]', '15 minutes by default (`idleRuntimeSessionTimeout`, up to 8 hours)', 'A user who comes back after a coffee break may get a fresh microVM.'], ['[[Max lifetime]]', '8 hours on microVMs (`maxLifetime`)', 'No session lives longer, even if it is busy.'], ['One synchronous request', '15 minutes', 'A longer job must stream or run in the background.'], ['One streaming response', '60 minutes', 'Long answers and long tool chains can keep streaming.'], ['Background (asynchronous) work', '8 hours on microVMs', 'Limited by the max lifetime of the session.'], ['Session hardware', '2 vCPU and 8 GB by default', 'Enough for an agent loop; heavy work belongs in tools.']],
          he: [['[[Idle timeout]]', '15 דקות כברירת מחדל (`idleRuntimeSessionTimeout`, עד 8 שעות)', 'משתמש שחוזר אחרי הפסקת קפה עלול לקבל microVM חדש.'], ['[[Max lifetime]]', '8 שעות על microVMs (`maxLifetime`)', 'אף session לא חי יותר, גם אם הוא עסוק.'], ['בקשה סינכרונית אחת', '15 דקות', 'עבודה ארוכה יותר חייבת streaming או ריצה ברקע.'], ['תשובת streaming אחת', '60 דקות', 'תשובות ארוכות ושרשראות כלים ארוכות יכולות להמשיך לזרום.'], ['עבודת רקע (אסינכרונית)', '8 שעות על microVMs', 'מוגבלת על ידי ה-max lifetime של ה-session.'], ['החומרה של session', '2 vCPU ו-8 GB כברירת מחדל', 'מספיק ללולאת סוכן; עבודה כבדה שייכת לכלים.']] } },
        { t: 'code', lang: 'python', code: 'lifecycleConfiguration={"idleRuntimeSessionTimeout": 300, "maxLifetime": 1800}', caption: { en: 'Both timers are settings of the runtime. This AWS example sets 5 idle minutes and a 30-minute lifetime (the values are in seconds).', he: 'שני הטיימרים הם הגדרות של ה-runtime. הדוגמה הזו של AWS קובעת 5 דקות idle וחיים של 30 דקות (הערכים בשניות).' } },
        { t: 'quiz', q: { en: 'Your agent keeps the shopping cart of the user in a Python variable. The settings are the defaults. The user goes to lunch for 20 minutes and continues with the same session ID. What happens?', he: 'הסוכן שלך שומר את עגלת הקניות של המשתמש במשתנה Python. ההגדרות הן ברירת המחדל. המשתמש יוצא לארוחת צהריים ל-20 דקות וממשיך עם אותו session ID. מה קורה?' },
          options: { en: ['The cart is still there, because the session ID is the same', 'The request fails, because the session ID is no longer valid', 'The request works, but in a fresh microVM: the variable, and the cart, are gone', 'Runtime restores the variable from a backup'], he: ['העגלה עדיין שם, כי ה-session ID זהה', 'הבקשה נכשלת, כי ה-session ID כבר לא תקף', 'הבקשה עובדת, אבל ב-microVM חדש: המשתנה, והעגלה, נעלמו', 'Runtime משחזר את המשתנה מגיבוי'] },
          answer: 2, explain: { en: 'After 15 idle minutes the session was terminated. The same ID is accepted again, but it gets a new, empty environment. This "the agent forgot everything after a break" bug is the most common surprise on Runtime.', he: 'אחרי 15 דקות idle ה-session הסתיים. אותו ID מתקבל שוב, אבל הוא מקבל סביבה חדשה וריקה. הבאג "הסוכן שכח הכול אחרי הפסקה" הוא ההפתעה הכי נפוצה ב-Runtime.' } },
        { t: 'quiz', q: { en: 'Where should the agent keep things that must survive the end of a session, such as the cart or the preferences of the user?', he: 'איפה הסוכן צריך לשמור דברים שחייבים לשרוד את סוף ה-session, כמו העגלה או ההעדפות של המשתמש?' },
          options: { en: ['Outside the microVM: in AgentCore Memory or in your own database', 'In a global Python variable', 'In a file on the disk of the microVM', 'In an environment variable'], he: ['מחוץ ל-microVM: ב-AgentCore Memory או במסד נתונים משלך', 'במשתנה Python גלובלי', 'בקובץ על הדיסק של ה-microVM', 'במשתנה סביבה'] },
          answer: 0, explain: { en: 'Variables and local files die with the microVM. Treat the session as a cache that makes the conversation fast, and treat durable storage as the truth.', he: 'משתנים וקבצים מקומיים מתים יחד עם ה-microVM. מתייחסים ל-session כאל cache שהופך את השיחה למהירה, ולאחסון קבוע כאל האמת.' } },
        { t: 'h', en: 'You pay for active CPU', he: 'משלמים על CPU פעיל' },
        { t: 'p', en: 'Think about what an agent does during a 30-second request: a few milliseconds of Python, then 10 seconds waiting for the model, a few milliseconds more, 5 seconds waiting for a tool. Runtime bills **per second** for the vCPU you actually use and for memory. Time spent waiting for a model answer uses almost no CPU, so it costs very little CPU. Memory is billed while the session lives.', he: 'תחשוב מה סוכן עושה במהלך בקשה של 30 שניות: כמה אלפיות שנייה של Python, אחר כך 10 שניות המתנה למודל, עוד כמה אלפיות שנייה, 5 שניות המתנה לכלי. Runtime מחייב **לפי שנייה** על ה-vCPU שבאמת השתמשת בו ועל זיכרון. זמן שמבלים בהמתנה לתשובת המודל כמעט לא משתמש ב-CPU, ולכן הוא עולה מעט מאוד CPU. זיכרון מחויב כל עוד ה-session חי.' },
        { t: 'quiz', q: { en: 'During one request your agent waits 30 seconds for the model to answer. How does that waiting time show up on the Runtime bill?', he: 'במהלך בקשה אחת הסוכן שלך מחכה 30 שניות לתשובת המודל. איך זמן ההמתנה הזה מופיע בחשבון של Runtime?' },
          options: { en: ['As 30 seconds of full vCPU', 'It is free: nothing is billed while waiting', 'As one fixed price per request', 'Almost no CPU charge, because CPU is billed by actual use; memory is still billed while the session lives'], he: ['כ-30 שניות של vCPU מלא', 'זה חינם: שום דבר לא מחויב בזמן המתנה', 'כמחיר קבוע אחד לכל בקשה', 'כמעט בלי חיוב CPU, כי CPU מחויב לפי שימוש בפועל; הזיכרון עדיין מחויב כל עוד ה-session חי'] },
          answer: 3, explain: { en: 'This is the key billing idea of Runtime and why it fits agents. The model tokens are a separate bill from the model provider. And memory does cost while the session is alive, so do not keep idle sessions longer than you need.', he: 'זה רעיון החיוב המרכזי של Runtime והסיבה שהוא מתאים לסוכנים. הטוקנים של המודל הם חשבון נפרד מספק המודל. והזיכרון כן עולה כל עוד ה-session חי, אז לא משאירים sessions במצב idle יותר ממה שצריך.' } },
        { t: 'order', prompt: { en: 'Put the life of one session in order.', he: 'סדר את החיים של session אחד.' }, items: { en: ['The app sends a request with a new runtimeSessionId', 'Runtime creates a dedicated microVM', 'Your entrypoint handles the request (Active)', 'The session waits for more requests (Idle)', 'The idle timeout passes', 'The microVM is destroyed and its memory is wiped'], he: ['האפליקציה שולחת בקשה עם runtimeSessionId חדש', 'Runtime יוצר microVM ייעודי', 'ה-entrypoint שלך מטפל בבקשה (Active)', 'ה-session מחכה לבקשות נוספות (Idle)', 'ה-idle timeout עובר', 'ה-microVM מושמד והזיכרון שלו נמחק'] }, explain: { en: 'Create on first use, reuse while alive, destroy at the end. Nothing is kept afterwards.', he: 'נוצר בשימוש הראשון, בשימוש חוזר כל עוד הוא חי, מושמד בסוף. שום דבר לא נשמר אחר כך.' } },
        { t: 'quiz', q: { en: 'A data-processing agent needs one session to work for 10 hours. You use the default microVM compute. What is true?', he: 'סוכן לעיבוד נתונים צריך ש-session אחד יעבוד 10 שעות. אתה משתמש ב-compute ברירת המחדל, microVMs. מה נכון?' },
          options: { en: ['It works if the agent reports that it is busy', 'It cannot: a microVM session lives at most 8 hours. Split the work, or use the Instances compute type', 'It works if you raise the idle timeout to 10 hours', 'It works if you stream the response'], he: ['זה עובד אם הסוכן מדווח שהוא עסוק', 'אי אפשר: session על microVM חי לכל היותר 8 שעות. מפצלים את העבודה, או משתמשים ב-compute מסוג Instances', 'זה עובד אם מעלים את ה-idle timeout ל-10 שעות', 'זה עובד אם עושים streaming לתשובה'] },
          answer: 1, explain: { en: 'Being busy protects a session from the **idle** timeout only. The max lifetime of 8 hours is a hard cap on microVMs. The Instances compute type allows sessions up to 14 days.', he: 'להיות עסוק מגן על session רק מפני ה-**idle** timeout. ה-max lifetime של 8 שעות הוא גבול קשיח על microVMs. סוג ה-compute שנקרא Instances מאפשר sessions של עד 14 ימים.' } },
        { t: 'reveal', q: { en: 'Interview question: "Why does AgentCore Runtime give every session its own microVM? Is that not wasteful?"', he: 'שאלת ראיון: "למה AgentCore Runtime נותן לכל session את ה-microVM שלו? זה לא בזבזני?"' },
          a: { en: 'Because an agent is stateful and risky in ways a normal API is not. During a session it holds the conversation, files and sometimes access tokens of the user in memory, and it may run code that a model generated. In a shared process, one bug could leak data between users. A microVM per session gives hard isolation of CPU, memory and file system, and when the session ends everything is destroyed. It is not wasteful, because billing follows actual CPU use, and an agent spends most of its time waiting for the model. The price is that session state is ephemeral, so durable state must go to Memory or a database.', he: 'כי סוכן הוא stateful ומסוכן בצורות ש-API רגיל לא. במהלך session הוא מחזיק בזיכרון את השיחה, קבצים ולפעמים access tokens של המשתמש, והוא עלול להריץ קוד שמודל יצר. בתהליך משותף, באג אחד יכול להדליף מידע בין משתמשים. microVM לכל session נותן בידוד קשיח של CPU, זיכרון ומערכת קבצים, וכשה-session נגמר הכול מושמד. זה לא בזבזני, כי החיוב הוא לפי שימוש בפועל ב-CPU, וסוכן מבלה את רוב הזמן בהמתנה למודל. המחיר הוא שה-state של session הוא זמני, ולכן state קבוע חייב ללכת ל-Memory או למסד נתונים.' } }
      ]
    },
    {
      id: 'm07l2', minutes: 13,
      title: { en: 'The agent contract', he: 'החוזה של הסוכן' },
      blocks: [
        { t: 'p', en: 'Runtime does not know Strands or LangGraph. It knows one thing: inside the microVM there is an **HTTP server**, and it sends requests to it. The rules for that server are the [[Service contract]]. For a normal agent (protocol `HTTP`):', he: 'Runtime לא מכיר את Strands או את LangGraph. הוא מכיר דבר אחד: בתוך ה-microVM יש **שרת HTTP**, והוא שולח אליו בקשות. הכללים לשרת הזה הם ה-[[Service contract]]. לסוכן רגיל (פרוטוקול `HTTP`):' },
        { t: 'list', en: ['Listen on host `0.0.0.0`, port **8080**.', '`POST /invocations`: the request of the user comes in as JSON. You answer with JSON, or with a stream ([[SSE]]).', '`GET /ping`: a health check. You answer `{"status": "Healthy"}` or `{"status": "HealthyBusy"}`.', '`GET /ws` (optional): a WebSocket for bidirectional streaming.', 'The code must run on **[[ARM64]]**: an ARM64 container image, or a ZIP built for ARM64.'], he: ['להאזין על host `0.0.0.0`, פורט **8080**.', '`POST /invocations`: הבקשה של המשתמש נכנסת כ-JSON. עונים ב-JSON, או ב-stream ([[SSE]]).', '`GET /ping`: בדיקת בריאות. עונים `{"status": "Healthy"}` או `{"status": "HealthyBusy"}`.', '`GET /ws` (אופציונלי): WebSocket ל-bidirectional streaming.', 'הקוד חייב לרוץ על **[[ARM64]]**: container image של ARM64, או ZIP שנבנה ל-ARM64.'] },
        { t: 'h', en: 'The SDK writes the server for you', he: 'ה-SDK כותב בשבילך את השרת' },
        { t: 'p', en: 'You could write this server yourself with any web framework. Nobody does. The AgentCore Python SDK (`pip install bedrock-agentcore`) has [[BedrockAgentCoreApp]]: you mark one function as the [[Entrypoint]], and the SDK serves `/invocations` and `/ping` on port 8080.', he: 'אפשר לכתוב את השרת הזה לבד עם כל web framework. אף אחד לא עושה את זה. ב-AgentCore Python SDK (`pip install bedrock-agentcore`) יש [[BedrockAgentCoreApp]]: מסמנים פונקציה אחת כ-[[Entrypoint]], וה-SDK מגיש את `/invocations` ואת `/ping` על פורט 8080.' },
        { t: 'code', lang: 'python', code: 'from bedrock_agentcore import BedrockAgentCoreApp\nfrom strands import Agent\n\napp = BedrockAgentCoreApp()\n\n@app.entrypoint\nasync def handler(request):\n    prompt = request.get("prompt")\n    if not isinstance(prompt, str):          # AWS security guidance: always enforce a string prompt\n        raise ValueError("prompt must be a string")\n    agent = Agent()\n    async for event in agent.stream_async(prompt):   # yielding = SSE streaming\n        yield event\n\napp.run()   # serves /invocations and /ping on port 8080', caption: { en: 'A complete agent for Runtime. The Strands part is three lines; the rest is the contract. In AWS docs you will also see the import `from bedrock_agentcore.runtime import BedrockAgentCoreApp`.', he: 'סוכן שלם ל-Runtime. החלק של Strands הוא שלוש שורות; השאר הוא החוזה. בתיעוד של AWS תראה גם את ה-import הזה: `from bedrock_agentcore.runtime import BedrockAgentCoreApp`.' } },
        { t: 'list', en: ['The entrypoint gets the JSON body as `request` (often named `payload`). The shape of that JSON is **your** decision. `{"prompt": "..."}` is only a habit.', 'It can also take a second argument: `(payload, context)`. AWS examples use `context.session_id` and `context.request_headers`.', '`return` a dict and the caller gets one JSON response. `yield` and the caller gets a stream.', 'Check the input. The payload comes from outside, so treat it like any user input.'], he: ['ה-entrypoint מקבל את גוף ה-JSON בתור `request` (הרבה פעמים קוראים לו `payload`). המבנה של ה-JSON הזה הוא החלטה **שלך**. `{"prompt": "..."}` הוא רק הרגל.', 'הוא יכול לקבל גם ארגומנט שני: `(payload, context)`. דוגמאות של AWS משתמשות ב-`context.session_id` וב-`context.request_headers`.', 'עושים `return` ל-dict והקורא מקבל תשובת JSON אחת. עושים `yield` והקורא מקבל stream.', 'בודקים את הקלט. ה-payload מגיע מבחוץ, אז מתייחסים אליו כמו לכל קלט של משתמש.'] },
        { t: 'fill', prompt: { en: 'Complete the Runtime wrapper around a Strands agent.', he: 'השלם את העטיפה של Runtime סביב סוכן Strands.' }, lang: 'python',
          code: 'from bedrock_agentcore import {{1}}\nfrom strands import Agent\n\napp = BedrockAgentCoreApp()\n\n@app.{{2}}\nasync def handler(request):\n    prompt = request.get("prompt")\n    agent = Agent()\n    async for event in agent.stream_async(prompt):\n        {{3}} event\n\napp.{{4}}()',
          blanks: [ { accept: ['BedrockAgentCoreApp'], hint: { en: 'the SDK class that builds the server', he: 'מחלקת ה-SDK שבונה את השרת' } }, { accept: ['entrypoint'], hint: { en: 'the decorator for the function behind /invocations', he: 'הדקורטור של הפונקציה שמאחורי /invocations' } }, { accept: ['yield'], hint: { en: 'the keyword that makes the response a stream', he: 'מילת המפתח שהופכת את התשובה ל-stream' } }, { accept: ['run'], hint: { en: 'starts the server on port 8080', he: 'מעלה את השרת על פורט 8080' } } ],
          explain: { en: 'Four identifiers are the whole contract in Python: the app class, the entrypoint decorator, `yield` for streaming, and `app.run()`.', he: 'ארבעה מזהים הם כל החוזה ב-Python: מחלקת ה-app, הדקורטור entrypoint, `yield` בשביל streaming, ו-`app.run()`.' } },
        { t: 'code', lang: 'bash', code: 'python main.py &\ncurl -X POST http://localhost:8080/invocations \\\n  -H \'Content-Type: application/json\' \\\n  -d \'{"prompt": "hello"}\'', caption: { en: 'Because it is plain HTTP, you can test the same code on your laptop with curl before any deploy.', he: 'מכיוון שזה HTTP רגיל, אפשר לבדוק את אותו קוד על הלפטופ עם curl לפני כל deploy.' } },
        { t: 'quiz', q: { en: 'Your entrypoint ends with `return {"result": text}`. Product now wants the words to appear one by one in the chat UI. What do you change in the entrypoint?', he: 'ה-entrypoint שלך מסתיים ב-`return {"result": text}`. ה-product רוצה עכשיו שהמילים יופיעו אחת-אחת בממשק הצ׳אט. מה משנים ב-entrypoint?' },
          options: { en: ['Change the port to 8000', 'Add a `/stream` path to the contract', 'Nothing: Runtime splits the JSON into words', 'Make it yield events (for example from `agent.stream_async`) instead of returning one dict'], he: ['משנים את הפורט ל-8000', 'מוסיפים נתיב `/stream` לחוזה', 'כלום: Runtime מפצל את ה-JSON למילים', 'גורמים לו לעשות yield לאירועים (למשל מ-`agent.stream_async`) במקום להחזיר dict אחד'] },
          answer: 3, explain: { en: 'Returning a dict gives one JSON response. Yielding makes the SDK answer with `text/event-stream` (SSE) on the same `/invocations` path. The client must then read the stream.', he: 'החזרת dict נותנת תשובת JSON אחת. yield גורם ל-SDK לענות ב-`text/event-stream` (SSE) באותו נתיב `/invocations`. ה-client צריך אז לקרוא את ה-stream.' } },
        { t: 'h', en: 'What /ping is for', he: 'בשביל מה /ping' },
        { t: 'p', en: 'Runtime calls `/ping` to learn the state of your session. `Healthy` means "alive and free". [[HealthyBusy]] means "alive and still working in the background". A session that reports `HealthyBusy` is not terminated by the idle timeout. You will use this for long tasks in lesson 4.', he: 'Runtime קורא ל-`/ping` כדי לדעת מה מצב ה-session שלך. `Healthy` אומר "חי ופנוי". [[HealthyBusy]] אומר "חי ועדיין עובד ברקע". session שמדווח `HealthyBusy` לא מסתיים בגלל ה-idle timeout. תשתמש בזה למשימות ארוכות בשיעור 4.' },
        { t: 'quiz', q: { en: 'What does a `HealthyBusy` answer from `/ping` tell Runtime?', he: 'מה תשובת `HealthyBusy` מ-`/ping` אומרת ל-Runtime?' },
          options: { en: ['The session is still working in the background, so do not terminate it as idle', 'The agent crashed and must be restarted', 'The agent needs more memory', 'The session is full and new requests must go to another microVM'], he: ['ה-session עדיין עובד ברקע, אז לא לסיים אותו כ-idle', 'הסוכן קרס וצריך להפעיל אותו מחדש', 'הסוכן צריך יותר זיכרון', 'ה-session מלא ובקשות חדשות צריכות ללכת ל-microVM אחר'] },
          answer: 0, explain: { en: 'It is a keep-alive signal. It protects the session from the idle timeout, up to the max lifetime of the session.', he: 'זה אות keep-alive. הוא מגן על ה-session מפני ה-idle timeout, עד ה-max lifetime של ה-session.' } },
        { t: 'h', en: 'Two ways to package the code', he: 'שתי דרכים לארוז את הקוד' },
        { t: 'table', head: { en: ['', 'Direct code deployment', 'Container'], he: ['', 'Direct code deployment', 'Container'] }, rows: {
          en: [['**What you ship**', 'A ZIP of your code and dependencies', 'An ARM64 [[Container image]] in Amazon ECR'], ['**Languages**', 'Python (3.10 to 3.14) or Node.js', 'Anything that runs in a container'], ['**Size limit**', '250 MB zipped, 750 MB unzipped', '2 GB compressed on V1, 10 GB on V2'], ['**Who patches the base**', 'AWS patches the language runtime', 'You own the base image'], ['**Docker on your laptop**', 'Not needed', 'Not needed for deploy: the CLI builds the image in AWS CodeBuild'], ['**Use it when**', 'Small packages, fast iteration', 'More than 250 MB, special system dependencies, or you already have container CI/CD']],
          he: [['**מה שולחים**', 'ZIP של הקוד והתלויות שלך', '[[Container image]] של ARM64 ב-Amazon ECR'], ['**שפות**', 'Python (3.10 עד 3.14) או Node.js', 'כל דבר שרץ ב-container'], ['**גבול גודל**', '250 MB מכווץ, 750 MB פרוס', '2 GB דחוס ב-V1, 10 GB ב-V2'], ['**מי מעדכן את הבסיס**', 'AWS מעדכנת את ה-runtime של השפה', 'ה-base image באחריותך'], ['**Docker על הלפטופ**', 'לא צריך', 'לא צריך בשביל deploy: ה-CLI בונה את ה-image ב-AWS CodeBuild'], ['**משתמשים בזה כש**', 'חבילות קטנות, איטרציה מהירה', 'יותר מ-250 MB, תלויות מערכת מיוחדות, או שכבר יש לך CI/CD של containers']] } },
        { t: 'note', kind: 'jargon', en: 'The CLI calls [[Direct code deployment]] the build type **CodeZip**. It is the same idea as AWS Lambda: you bring code, AWS brings the language runtime.', he: 'ה-CLI קורא ל-[[Direct code deployment]] בשם build type **CodeZip**. זה אותו רעיון כמו ב-AWS Lambda: אתה מביא קוד, AWS מביאה את ה-runtime של השפה.' },
        { t: 'quiz', q: { en: 'A colleague builds the agent image on an Intel laptop with a plain `docker build`, pushes it to ECR and creates a runtime. The agent does not start. What is the first thing to check?', he: 'עמית בונה את ה-image של הסוכן על לפטופ Intel עם `docker build` רגיל, דוחף אותו ל-ECR ויוצר runtime. הסוכן לא עולה. מה הדבר הראשון לבדוק?' },
          options: { en: ['Whether the image is larger than 250 MB', 'Whether the image was built for linux/arm64', 'Whether the entrypoint returns a dict', 'Whether the session ID is a UUID'], he: ['האם ה-image גדול מ-250 MB', 'האם ה-image נבנה ל-linux/arm64', 'האם ה-entrypoint מחזיר dict', 'האם ה-session ID הוא UUID'] },
          answer: 1, explain: { en: 'Runtime runs ARM64 only, and an Intel laptop builds x86 images by default. 250 MB is the limit of a code ZIP, not of an image. Building through the AgentCore CLI avoids this mistake, because the build happens in AWS.', he: 'Runtime מריץ רק ARM64, ולפטופ Intel בונה כברירת מחדל images של x86. 250 MB הוא הגבול של ZIP של קוד, לא של image. בנייה דרך ה-AgentCore CLI מונעת את הטעות הזו, כי הבנייה קורית ב-AWS.' } },
        { t: 'quiz', q: { en: 'Your agent needs a machine-learning library and a system package. Together the dependencies are about 400 MB zipped. Which packaging do you choose?', he: 'הסוכן שלך צריך ספריית machine learning וחבילת מערכת. יחד התלויות הן בערך 400 MB מכווץ. באיזו אריזה בוחרים?' },
          options: { en: ['Direct code deployment, because it needs no Docker', 'Direct code deployment with two ZIP files', 'A container image', 'Neither: Runtime cannot host it'], he: ['Direct code deployment, כי לא צריך Docker', 'Direct code deployment עם שני קובצי ZIP', 'Container image', 'אף אחת: Runtime לא יכול לארח את זה'] },
          answer: 2, explain: { en: 'A code package is limited to 250 MB zipped, and system packages are a classic reason for a container. An image can be 2 GB on V1 and 10 GB on V2.', he: 'חבילת קוד מוגבלת ל-250 MB מכווץ, וחבילות מערכת הן סיבה קלאסית ל-container. image יכול להיות 2 GB ב-V1 ו-10 GB ב-V2.' } },
        { t: 'h', en: 'Four protocols', he: 'ארבעה פרוטוקולים' },
        { t: 'p', en: 'An agent runtime is not always an agent. The same service can host a tool server or an agent that other agents call. You choose a **protocol** when you create the runtime, and each protocol has its own contract:', he: 'agent runtime הוא לא תמיד סוכן. אותו שירות יכול לארח שרת כלים או סוכן שסוכנים אחרים קוראים לו. בוחרים **פרוטוקול** כשיוצרים את ה-runtime, ולכל פרוטוקול יש חוזה משלו:' },
        { t: 'table', head: { en: ['Protocol', 'Port', 'Path', 'Use it to host'], he: ['פרוטוקול', 'פורט', 'נתיב', 'משתמשים בו כדי לארח'] }, rows: {
          en: [['HTTP', '8080', '`/invocations` (and `/ws`)', 'A normal agent'], ['[[MCP]]', '8000', '`/mcp`', 'A tool server that agents call as MCP clients'], ['[[A2A]]', '9000', '`/` and the Agent Card at `/.well-known/agent-card.json`', 'An agent that other agents call'], ['AG-UI', '8080', '`/invocations` (SSE) and `/ws`', 'An agent that streams events to a user interface']],
          he: [['HTTP', '8080', '`/invocations` (ו-`/ws`)', 'סוכן רגיל'], ['[[MCP]]', '8000', '`/mcp`', 'שרת כלים שסוכנים קוראים לו כ-MCP clients'], ['[[A2A]]', '9000', '`/` וה-Agent Card ב-`/.well-known/agent-card.json`', 'סוכן שסוכנים אחרים קוראים לו'], ['AG-UI', '8080', '`/invocations` (SSE) ו-`/ws`', 'סוכן שמזרים אירועים לממשק משתמש']] } },
        { t: 'quiz', q: { en: 'Your team wrote a set of "inventory" tools as an MCP server and wants to host it on Runtime so that many agents can use it. Which protocol, port and path?', he: 'הצוות שלך כתב קבוצת כלי "מלאי" כ-MCP server ורוצה לארח אותו ב-Runtime כדי שהרבה סוכנים ישתמשו בו. איזה פרוטוקול, פורט ונתיב?' },
          options: { en: ['MCP, port 8000, path /mcp', 'HTTP, port 8080, path /invocations', 'A2A, port 9000, path /', 'AG-UI, port 8080, path /ws'], he: ['MCP, פורט 8000, נתיב /mcp', 'HTTP, פורט 8080, נתיב /invocations', 'A2A, פורט 9000, נתיב /', 'AG-UI, פורט 8080, נתיב /ws'] },
          answer: 0, explain: { en: 'A tool server speaks MCP, and the MCP contract on Runtime is port 8000 and path `/mcp`. HTTP on 8080 is for an agent. A2A is for agent-to-agent calls.', he: 'שרת כלים מדבר MCP, והחוזה של MCP ב-Runtime הוא פורט 8000 ונתיב `/mcp`. HTTP על 8080 מיועד לסוכן. A2A מיועד לקריאות בין סוכנים.' } },
        { t: 'h', en: 'Any framework fits', he: 'כל framework מתאים' },
        { t: 'code', lang: 'python', code: 'from langgraph.graph import StateGraph, START\nfrom bedrock_agentcore.runtime import BedrockAgentCoreApp\napp = BedrockAgentCoreApp()\n\ngraph = graph_builder.compile()                  # your normal LangGraph graph\n\n@app.entrypoint\ndef agent_invocation(payload, context):\n    msg = {"messages": [{"role": "user", "content": str(payload.get("prompt", ""))}]}\n    out = graph.invoke(msg)\n    return {"result": out["messages"][-1].content}\n\napp.run()', caption: { en: 'The same wrapper around a LangGraph agent. Only the three lines inside the entrypoint are different.', he: 'אותה עטיפה סביב סוכן LangGraph. רק שלוש השורות שבתוך ה-entrypoint שונות.' } },
        { t: 'match', prompt: { en: 'Match each part of the contract to its job.', he: 'התאם כל חלק בחוזה לתפקיד שלו.' }, pairs: [
          { a: 'POST /invocations', b: { en: 'Receives the request and returns the answer', he: 'מקבל את הבקשה ומחזיר את התשובה' } },
          { a: 'GET /ping', b: { en: 'Tells Runtime: Healthy or HealthyBusy', he: 'אומר ל-Runtime: Healthy או HealthyBusy' } },
          { a: 'GET /ws', b: { en: 'Optional WebSocket for bidirectional streaming', he: 'WebSocket אופציונלי ל-bidirectional streaming' } },
          { a: '8080', b: { en: 'The port of the HTTP protocol', he: 'הפורט של פרוטוקול HTTP' } },
          { a: 'linux/arm64', b: { en: 'The architecture the code must be built for', he: 'הארכיטקטורה שהקוד חייב להיבנות בשבילה' } }
        ] },
        { t: 'reveal', q: { en: 'Interview question: "What exactly does BedrockAgentCoreApp do? Could we live without it?"', he: 'שאלת ראיון: "מה בדיוק BedrockAgentCoreApp עושה? אפשר לחיות בלעדיו?"' },
          a: { en: 'It is a thin HTTP server that implements the Runtime service contract. It listens on port 8080, routes `POST /invocations` to the function I mark with `@app.entrypoint`, answers `GET /ping` with Healthy or HealthyBusy, turns a returned dict into JSON and a generator into an SSE stream, and gives me helpers for background tasks. We could live without it: Runtime only needs something that honors the contract, so any web server on ARM64 with those paths would work. But the SDK saves that code and stays up to date with the contract, so there is rarely a reason to write it ourselves.', he: 'זה שרת HTTP דק שמממש את ה-service contract של Runtime. הוא מאזין על פורט 8080, מנתב את `POST /invocations` לפונקציה שסימנתי ב-`@app.entrypoint`, עונה ל-`GET /ping` עם Healthy או HealthyBusy, הופך dict שהוחזר ל-JSON ו-generator ל-stream של SSE, ונותן לי עזרים למשימות רקע. אפשר לחיות בלעדיו: Runtime צריך רק משהו שמקיים את החוזה, אז כל שרת web על ARM64 עם הנתיבים האלה יעבוד. אבל ה-SDK חוסך את הקוד הזה ונשאר מעודכן עם החוזה, כך שכמעט אין סיבה לכתוב את זה לבד.' } }
      ]
    },
    {
      id: 'm07l3', minutes: 14,
      title: { en: 'The AgentCore CLI workflow', he: 'העבודה עם ה-AgentCore CLI' },
      blocks: [
        { t: 'p', en: 'To get code onto Runtime you need a package, an IAM role, the runtime resource and usually more (memory, a gateway). The [[AgentCore CLI]] does all of it from one project folder. It is a Node.js tool, version 1.0 since October 2026, and under the hood it uses the AWS CDK, the AWS toolkit that defines infrastructure in code.', he: 'כדי להעלות קוד ל-Runtime צריך חבילה, IAM role, את משאב ה-runtime ובדרך כלל עוד (memory, gateway). ה-[[AgentCore CLI]] עושה את כל זה מתיקיית פרויקט אחת. זה כלי Node.js, בגרסה 1.0 מאוקטובר 2026, ומתחת למכסה הוא משתמש ב-AWS CDK, ערכת הכלים של AWS שמגדירה תשתית בקוד.' },
        { t: 'code', lang: 'bash', code: 'npm install -g @aws/agentcore\nagentcore --version', caption: { en: 'You need: Node.js 20.12 or newer, npm, AWS credentials, Python 3.10 or newer, and `uv` (a Python package manager).', he: 'צריך: Node.js 20.12 ומעלה, npm, AWS credentials, Python 3.10 ומעלה, ו-`uv` (מנהל חבילות ל-Python).' } },
        { t: 'note', kind: 'warn', en: '**Old blog posts will confuse you.** Until 2026 there was a Python tool, the [[Starter toolkit]], with commands like `agentcore configure` and `agentcore launch` and a file named `.bedrock_agentcore.yaml`. It is **deprecated**: its own README says not to use it. Both tools install a command named `agentcore`. If `agentcore --version` gives an error, the old one is probably in the way: run `pip uninstall bedrock-agentcore-starter-toolkit`. When a tutorial says `configure` or `launch`, it is old: today you use `create` and `deploy`.', he: '**פוסטים ישנים בבלוגים יבלבלו אותך.** עד 2026 היה כלי Python, ה-[[Starter toolkit]], עם פקודות כמו `agentcore configure` ו-`agentcore launch` וקובץ בשם `.bedrock_agentcore.yaml`. הוא **הוצא משימוש**: ה-README שלו עצמו אומר לא להשתמש בו. שני הכלים מתקינים פקודה בשם `agentcore`. אם `agentcore --version` נותן שגיאה, כנראה הישן מפריע: הרץ `pip uninstall bedrock-agentcore-starter-toolkit`. כשמדריך אומר `configure` או `launch`, הוא ישן: היום משתמשים ב-`create` וב-`deploy`.' },
        { t: 'h', en: 'The commands', he: 'הפקודות' },
        { t: 'table', head: { en: ['Command', 'What it does'], he: ['פקודה', 'מה היא עושה'] }, rows: {
          en: [['`agentcore create`', 'Makes a new project folder from a template.'], ['`agentcore dev`', 'Runs the agent **locally** with hot reload. `--mode browser` opens the Agent Inspector, a local test UI.'], ['`agentcore build`', 'Validates the project and builds the artifacts.'], ['`agentcore deploy`', 'Deploys everything in the project to AWS (CDK synth + deploy).'], ['`agentcore status`', 'Shows what is deployed. Add `--json` to get the ARNs.'], ['`agentcore invoke`', 'Sends a request to the deployed agent, or to the local one with `--local`.'], ['`agentcore logs`', 'Shows the logs of the agent from CloudWatch.'], ['`agentcore traces`', 'Lists and shows traces: what the agent did, step by step.'], ['`agentcore add` / `remove`', 'Adds or removes a resource in the project: a runtime, memory, a gateway and more.']],
          he: [['`agentcore create`', 'יוצרת תיקיית פרויקט חדשה מתוך template.'], ['`agentcore dev`', 'מריצה את הסוכן **מקומית** עם hot reload. `--mode browser` פותח את ה-Agent Inspector, ממשק בדיקה מקומי.'], ['`agentcore build`', 'בודקת את הפרויקט ובונה את ה-artifacts.'], ['`agentcore deploy`', 'פורסת את כל מה שבפרויקט ל-AWS (CDK synth + deploy).'], ['`agentcore status`', 'מראה מה פרוס. מוסיפים `--json` כדי לקבל את ה-ARNs.'], ['`agentcore invoke`', 'שולחת בקשה לסוכן הפרוס, או לסוכן המקומי עם `--local`.'], ['`agentcore logs`', 'מציגה את הלוגים של הסוכן מ-CloudWatch.'], ['`agentcore traces`', 'מציגה רשימה ופרטים של traces: מה הסוכן עשה, צעד אחרי צעד.'], ['`agentcore add` / `remove`', 'מוסיפה או מסירה משאב בפרויקט: runtime, memory, gateway ועוד.']] } },
        { t: 'note', kind: 'jargon', en: 'An **ARN** (Amazon Resource Name) is the full unique name of a resource in AWS. A runtime ARN looks like `arn:aws:bedrock-agentcore:<region>:<account>:runtime/<name>-<suffix>`. Your app needs it to call the agent.', he: '**ARN** (Amazon Resource Name) הוא השם הייחודי המלא של משאב ב-AWS. ARN של runtime נראה כך: `arn:aws:bedrock-agentcore:<region>:<account>:runtime/<name>-<suffix>`. האפליקציה שלך צריכה אותו כדי לקרוא לסוכן.' },
        { t: 'h', en: 'Create: what you get', he: 'Create: מה מקבלים' },
        { t: 'code', lang: 'bash', code: 'agentcore create --name MyProject --template agent-python-strands\ncd MyProject', caption: { en: 'This template gives a code-based Strands agent with a CodeZip build and Memory. Other templates named in the docs include `agent-python-strands-container`, `agent-typescript-strands`, `a2a-python-strands`, `agui-python-strands` and `mcp-python-fastmcp`.', he: 'ה-template הזה נותן סוכן Strands מבוסס קוד עם build מסוג CodeZip ועם Memory. templates אחרים שמוזכרים בתיעוד כוללים את `agent-python-strands-container`, `agent-typescript-strands`, `a2a-python-strands`, `agui-python-strands` ו-`mcp-python-fastmcp`.' } },
        { t: 'code', lang: 'text', code: 'MyProject/\n├── agentcore/\n│   ├── .env.local          # local secrets (do not commit)\n│   ├── agentcore.json      # project spec: runtimes, harnesses, memory, gateways, credentials\n│   ├── aws-targets.json    # accounts + Regions to deploy to\n│   └── cdk/                # generated CDK app\n└── app/agent/\n    ├── main.py             # Runtime entrypoint + Strands agent\n    ├── memory/session.py   # AgentCore Memory session manager\n    ├── model/load.py       # model selection\n    └── pyproject.toml', caption: { en: '`main.py` is the code from the previous lesson. [[agentcore.json]] is the list of what `deploy` will create.', he: '`main.py` הוא הקוד מהשיעור הקודם. [[agentcore.json]] הוא הרשימה של מה ש-`deploy` ייצור.' } },
        { t: 'note', kind: 'info', en: '`agentcore create --name X` **without** `--template` creates a managed **harness** project: configuration only, no agent code. And `agentcore` with no arguments opens an interactive menu.', he: '`agentcore create --name X` **בלי** `--template` יוצר פרויקט **harness** מנוהל: קונפיגורציה בלבד, בלי קוד סוכן. ו-`agentcore` בלי ארגומנטים פותח תפריט אינטראקטיבי.' },
        { t: 'quiz', q: { en: 'You ran `agentcore create --name SupportBot` and expected a `main.py` with a Strands agent. There is no agent code in the project. Why?', he: 'הרצת `agentcore create --name SupportBot` וציפית ל-`main.py` עם סוכן Strands. אין קוד סוכן בפרויקט. למה?' },
          options: { en: ['The CLI failed silently', 'Python is not installed', 'The code is created only by `agentcore deploy`', 'Without `--template` the CLI creates a managed harness project, which is configuration only'], he: ['ה-CLI נכשל בשקט', 'Python לא מותקן', 'הקוד נוצר רק על ידי `agentcore deploy`', 'בלי `--template` ה-CLI יוצר פרויקט harness מנוהל, שהוא קונפיגורציה בלבד'] },
          answer: 3, explain: { en: 'The default follows the AWS recommendation: start with the harness. For your own code on Runtime, pass a template such as `--template agent-python-strands`.', he: 'ברירת המחדל הולכת לפי ההמלצה של AWS: להתחיל עם ה-harness. בשביל קוד משלך ב-Runtime, מעבירים template כמו `--template agent-python-strands`.' } },
        { t: 'h', en: 'Dev, deploy, invoke, look', he: 'Dev, deploy, invoke, להסתכל' },
        { t: 'list', en: ['**`agentcore dev`** runs the agent on your machine. Change the code and it reloads. Find bugs here: it is free and fast. If the port is taken: `agentcore dev --port 8081`.', '**`agentcore deploy`** packages the code and creates the AWS resources. The first run also prepares the account for CDK ("bootstrap") and takes a few minutes.', '**`agentcore invoke --runtime agent --payload \'{"prompt":"..."}\'`** calls the deployed runtime named `agent`.', '**`agentcore logs runtime --since 30m --level error`** and **`agentcore traces runtime list --since 30m`** show what happened.'], he: ['**`agentcore dev`** מריצה את הסוכן על המחשב שלך. משנים את הקוד והוא נטען מחדש. כאן מוצאים באגים: זה חינם ומהיר. אם הפורט תפוס: `agentcore dev --port 8081`.', '**`agentcore deploy`** אורזת את הקוד ויוצרת את המשאבים ב-AWS. ההרצה הראשונה גם מכינה את החשבון ל-CDK ("bootstrap") ולוקחת כמה דקות.', '**`agentcore invoke --runtime agent --payload \'{"prompt":"..."}\'`** קוראת ל-runtime הפרוס בשם `agent`.', '**`agentcore logs runtime --since 30m --level error`** ו-**`agentcore traces runtime list --since 30m`** מראות מה קרה.'] },
        { t: 'quiz', q: { en: 'You changed the system prompt in `main.py` and want to check the change. What is the fastest correct way?', he: 'שינית את ה-system prompt ב-`main.py` ואתה רוצה לבדוק את השינוי. מה הדרך הנכונה והמהירה ביותר?' },
          options: { en: ['Run `agentcore dev` and test locally; deploy only when it works', 'Run `agentcore deploy` after every edit', 'Edit the code in the AWS console', 'Run `agentcore status`'], he: ['להריץ `agentcore dev` ולבדוק מקומית; לעשות deploy רק כשזה עובד', 'להריץ `agentcore deploy` אחרי כל עריכה', 'לערוך את הקוד בקונסול של AWS', 'להריץ `agentcore status`'] },
          answer: 0, explain: { en: 'The local loop with hot reload takes seconds. A deploy takes much longer. Because the code follows the same HTTP contract locally and on Runtime, what works in `dev` behaves the same after deploy.', he: 'הלולאה המקומית עם hot reload לוקחת שניות. deploy לוקח הרבה יותר. מכיוון שהקוד מקיים את אותו חוזה HTTP מקומית וב-Runtime, מה שעובד ב-`dev` מתנהג אותו דבר אחרי deploy.' } },
        { t: 'terminal', title: { en: 'Terminal lab: from nothing to a deployed agent', he: 'מעבדת טרמינל: מכלום לסוכן פרוס' }, intro: { en: 'Walk the whole path once: install, create, run locally, deploy, invoke, read the logs. The output here is only an illustration.', he: 'עבור פעם אחת על כל המסלול: התקנה, יצירה, הרצה מקומית, deploy, invoke, קריאת לוגים. הפלט כאן הוא רק המחשה.' }, shell: 'bash — ~/projects',
          steps: [
            { ask: { en: 'Install the AgentCore CLI globally with npm.', he: 'התקן את ה-AgentCore CLI גלובלית עם npm.' }, accept: ['^npm\\s+(install|i)\\s+(-g|--global)\\s+@aws/agentcore(@\\S+)?$', '^npm\\s+(install|i)\\s+@aws/agentcore(@\\S+)?\\s+(-g|--global)$'], hint: 'npm install -g @aws/agentcore', output: 'added 1 package', wrong: 'The package is @aws/agentcore, and it must be installed globally (-g).' },
            { ask: { en: 'Create a project named `MyProject` from the Python Strands template (code-based, not a harness).', he: 'צור פרויקט בשם `MyProject` מתוך ה-template של Python Strands (מבוסס קוד, לא harness).' }, accept: ['^agentcore\\s+create\\s+(?=.*--name[= ]\\s*["\']?MyProject\\b)(?=.*--template[= ]\\s*["\']?agent-python-strands["\']?(\\s|$)).+$'], hint: 'agentcore create --name MyProject --template agent-python-strands', output: 'Created project MyProject\n  agentcore/agentcore.json\n  app/agent/main.py', wrong: 'You need both --name MyProject and --template agent-python-strands.' },
            { ask: { en: 'Go into the project folder.', he: 'היכנס לתיקיית הפרויקט.' }, accept: ['^cd\\s+(\\./)?MyProject/?$'], hint: 'cd MyProject', output: '' },
            { ask: { en: 'Run the agent locally and open the Agent Inspector in the browser.', he: 'הרץ את הסוכן מקומית ופתח את ה-Agent Inspector בדפדפן.' }, accept: ['^agentcore\\s+dev\\s+--mode[= ]\\s*browser$'], hint: 'agentcore dev --mode browser', output: 'Local agent running\nAgent Inspector opened in your browser\n(press Ctrl+C to stop)', wrong: 'The local command is "agentcore dev". The default mode is headless: add --mode browser.' },
            { ask: { en: 'It works locally. Deploy the project to AWS.', he: 'זה עובד מקומית. עשה deploy לפרויקט ל-AWS.' }, accept: ['^agentcore\\s+deploy(\\s+--yes)?$'], hint: 'agentcore deploy', output: 'Synthesizing...\nDeploying stack...\nDeployed: runtime agent' },
            { ask: { en: 'Call the deployed runtime named `agent` with the JSON payload `{"prompt":"Hello, what can you do?"}`.', he: 'קרא ל-runtime הפרוס בשם `agent` עם ה-payload הזה ב-JSON: `{"prompt":"Hello, what can you do?"}`.' }, accept: ['^agentcore\\s+invoke\\s+(?=.*--runtime[= ]\\s*["\']?agent\\b)(?=.*--payload[= ]\\s*\\S).+$'], hint: 'agentcore invoke --runtime agent --payload \'{"prompt":"Hello, what can you do?"}\'', output: 'Hello! I can answer questions and use my tools to help you.', wrong: 'You need: agentcore invoke --runtime <name> --payload \'<json>\'' },
            { ask: { en: 'Something looked wrong. Show the runtime logs of the last 30 minutes, only at level error.', he: 'משהו נראה לא בסדר. הצג את הלוגים של ה-runtime מ-30 הדקות האחרונות, רק ברמת error.' }, accept: ['^agentcore\\s+logs\\s+runtime\\b(?=.*--since[= ]\\s*30m\\b)(?=.*--level[= ]\\s*error\\b).*$'], hint: 'agentcore logs runtime --since 30m --level error', output: '(no error lines in the last 30 minutes)', wrong: 'The form is: agentcore logs runtime --since <time> --level <level>' }
          ],
          done: { en: 'That is the whole daily loop: create once, then dev → deploy → invoke → logs and traces, again and again.', he: 'זו כל הלולאה היומית: יוצרים פעם אחת, ואז dev ← deploy ← invoke ← logs ו-traces, שוב ושוב.' } },
        { t: 'h', en: 'Add and remove resources', he: 'מוסיפים ומסירים משאבים' },
        { t: 'p', en: '`agentcore add` changes the **project** (it edits [[agentcore.json]]). Nothing changes in AWS until you run `agentcore deploy` again. For example, `agentcore add runtime --name worker --language python --protocol HTTP` adds a second runtime; the protocol can be `HTTP`, `MCP`, `A2A` or `AGUI`. There are also `agentcore add memory`, `add gateway`, `add gateway-target`, `add policy-engine` and more. After a deploy, a memory resource is given to your agent code as environment variables named `MEMORY_<NAME>_ID` and `MEMORY_<NAME>_ARN`.', he: '`agentcore add` משנה את ה**פרויקט** (היא עורכת את [[agentcore.json]]). שום דבר לא משתנה ב-AWS עד שמריצים שוב `agentcore deploy`. לדוגמה, `agentcore add runtime --name worker --language python --protocol HTTP` מוסיפה runtime שני; הפרוטוקול יכול להיות `HTTP`, `MCP`, `A2A` או `AGUI`. יש גם `agentcore add memory`, `add gateway`, `add gateway-target`, `add policy-engine` ועוד. אחרי deploy, משאב memory ניתן לקוד הסוכן שלך כמשתני סביבה בשם `MEMORY_<NAME>_ID` ו-`MEMORY_<NAME>_ARN`.' },
        { t: 'fill', prompt: { en: 'Complete three everyday commands: get the ARNs of what is deployed, list recent traces, and delete everything at the end of a test.', he: 'השלם שלוש פקודות יומיומיות: קבלת ה-ARNs של מה שפרוס, רשימת traces אחרונים, ומחיקת הכול בסוף בדיקה.' }, lang: 'bash',
          code: 'agentcore {{1}} --json\nagentcore traces runtime {{2}} --since 30m\nagentcore remove {{3}} --yes && agentcore {{4}} --yes',
          blanks: [ { accept: ['status'], hint: { en: 'shows what is deployed', he: 'מראה מה פרוס' } }, { accept: ['list'], hint: { en: 'the sub-command that lists traces', he: 'תת-הפקודה שמציגה רשימת traces' } }, { accept: ['all'], hint: { en: 'remove every resource from the project', he: 'להסיר כל משאב מהפרויקט' } }, { accept: ['deploy'], hint: { en: 'changes reach AWS only with this command', he: 'שינויים מגיעים ל-AWS רק עם הפקודה הזו' } } ],
          explain: { en: '`remove` only empties the project spec. The second command deploys that empty spec, and that is what deletes the resources in AWS. Forget it, and you keep paying.', he: '`remove` רק מרוקנת את ה-spec של הפרויקט. הפקודה השנייה עושה deploy ל-spec הריק, וזה מה שמוחק את המשאבים ב-AWS. שוכחים אותה, וממשיכים לשלם.' } },
        { t: 'quiz', q: { en: 'You ran `agentcore add memory` and then `agentcore invoke`. The agent behaves exactly as before: no memory. What did you forget?', he: 'הרצת `agentcore add memory` ואחר כך `agentcore invoke`. הסוכן מתנהג בדיוק כמו קודם: בלי זיכרון. מה שכחת?' },
          options: { en: ['To restart your terminal', 'To run `agentcore deploy`: `add` only changes the project files', 'To run `agentcore status`', 'To install the starter toolkit'], he: ['להפעיל מחדש את הטרמינל', 'להריץ `agentcore deploy`: `add` משנה רק את קובצי הפרויקט', 'להריץ `agentcore status`', 'להתקין את ה-starter toolkit'] },
          answer: 1, explain: { en: 'The project is the plan and AWS is the reality. `add` and `remove` edit the plan. Only `deploy` makes reality match it. And your agent code must of course use the memory too.', he: 'הפרויקט הוא התוכנית ו-AWS היא המציאות. `add` ו-`remove` עורכות את התוכנית. רק `deploy` גורם למציאות להתאים לה. וכמובן שקוד הסוכן שלך צריך גם להשתמש בזיכרון.' } },
        { t: 'quiz', q: { en: 'A year ago you followed a tutorial with `agentcore configure`. Today you run `npm install -g @aws/agentcore`, and then `agentcore --version` prints an error. What is the likely cause?', he: 'לפני שנה עקבת אחרי מדריך עם `agentcore configure`. היום אתה מריץ `npm install -g @aws/agentcore`, ואז `agentcore --version` מדפיס שגיאה. מה הסיבה הסבירה?' },
          options: { en: ['Your AWS credentials expired', 'Node.js cannot run CLIs', 'The old Python starter toolkit also installed a command named `agentcore`; uninstall it with pip', 'The CLI works only inside a project folder'], he: ['ה-AWS credentials שלך פגו', 'Node.js לא יכול להריץ CLIs', 'ה-starter toolkit הישן ב-Python התקין גם הוא פקודה בשם `agentcore`; מסירים אותו עם pip', 'ה-CLI עובד רק בתוך תיקיית פרויקט'] },
          answer: 2, explain: { en: 'Two tools, one command name. The shell finds the old one first. `pip uninstall bedrock-agentcore-starter-toolkit` fixes it.', he: 'שני כלים, שם פקודה אחד. ה-shell מוצא קודם את הישן. `pip uninstall bedrock-agentcore-starter-toolkit` מתקן את זה.' } },
        { t: 'match', prompt: { en: 'Match the goal to the command.', he: 'התאם את המטרה לפקודה.' }, pairs: [
          { a: { en: 'Try a code change in seconds, on my laptop', he: 'לנסות שינוי בקוד תוך שניות, על הלפטופ שלי' }, b: 'agentcore dev' },
          { a: { en: 'Put the project in my AWS account', he: 'לשים את הפרויקט בחשבון ה-AWS שלי' }, b: 'agentcore deploy' },
          { a: { en: 'Get the ARN of the deployed runtime', he: 'לקבל את ה-ARN של ה-runtime הפרוס' }, b: 'agentcore status --json' },
          { a: { en: 'See which tools the agent called in a request', he: 'לראות לאילו כלים הסוכן קרא בבקשה' }, b: 'agentcore traces' },
          { a: { en: 'Read the Python error behind a failed request', he: 'לקרוא את שגיאת ה-Python שמאחורי בקשה שנכשלה' }, b: 'agentcore logs' }
        ] },
        { t: 'reveal', q: { en: 'A teammate asks: "What actually happens when I type `agentcore deploy`?" Explain it.', he: 'חבר לצוות שואל: "מה בעצם קורה כשאני מקליד `agentcore deploy`?" הסבר.' },
          a: { en: 'The CLI reads the project spec in `agentcore/agentcore.json` and the list of target accounts and Regions. It builds the artifact: a ZIP for a CodeZip project, or a container image that is built in AWS CodeBuild, so I need no local Docker. Then it uses the AWS CDK to synthesize and deploy a stack with everything in the spec: the agent runtime, its IAM role, and things like memory or a gateway. On the first run it also bootstraps CDK in the account, which is why the first deploy takes minutes. After that, `agentcore status` shows the resources and `agentcore invoke` calls them.', he: 'ה-CLI קורא את ה-spec של הפרויקט ב-`agentcore/agentcore.json` ואת רשימת החשבונות וה-Regions של היעד. הוא בונה את ה-artifact: ZIP לפרויקט CodeZip, או container image שנבנה ב-AWS CodeBuild, כך שלא צריך Docker מקומי. אחר כך הוא משתמש ב-AWS CDK כדי לעשות synthesize ו-deploy ל-stack עם כל מה שב-spec: ה-agent runtime, ה-IAM role שלו, ודברים כמו memory או gateway. בהרצה הראשונה הוא גם עושה bootstrap ל-CDK בחשבון, ולכן ה-deploy הראשון לוקח דקות. אחרי זה, `agentcore status` מראה את המשאבים ו-`agentcore invoke` קורא להם.' } }
      ]
    },
    {
      id: 'm07l4', minutes: 14,
      title: { en: 'Calling the agent from an app', he: 'קוראים לסוכן מאפליקציה' },
      blocks: [
        { t: 'p', en: 'The CLI is for you. Your users reach the agent through **your application**: a web backend, a mobile backend, a Lambda function. The application calls one API operation: `InvokeAgentRuntime`.', he: 'ה-CLI הוא בשבילך. המשתמשים שלך מגיעים לסוכן דרך **האפליקציה שלך**: backend של web, backend של מובייל, פונקציית Lambda. האפליקציה קוראת לפעולת API אחת: `InvokeAgentRuntime`.' },
        { t: 'h', en: 'Two clients: control plane and data plane', he: 'שני clients: control plane ו-data plane' },
        { t: 'table', head: { en: ['', '[[Control plane]]', '[[Data plane]]'], he: ['', '[[Control plane]]', '[[Data plane]]'] }, rows: {
          en: [['**boto3 client name**', '`bedrock-agentcore-control`', '`bedrock-agentcore`'], ['**What it does**', 'Creates, updates and deletes resources', 'Uses them at run time'], ['**Typical operations**', '`CreateAgentRuntime`, `UpdateAgentRuntime`, `GetAgentRuntime`, `CreateAgentRuntimeEndpoint`', '`InvokeAgentRuntime`, `StopRuntimeSession`'], ['**Who calls it**', 'The CLI, your CI/CD pipeline', 'Your application, on every user message']],
          he: [['**שם ה-client ב-boto3**', '`bedrock-agentcore-control`', '`bedrock-agentcore`'], ['**מה הוא עושה**', 'יוצר, מעדכן ומוחק משאבים', 'משתמש בהם בזמן ריצה'], ['**פעולות טיפוסיות**', '`CreateAgentRuntime`, `UpdateAgentRuntime`, `GetAgentRuntime`, `CreateAgentRuntimeEndpoint`', '`InvokeAgentRuntime`, `StopRuntimeSession`'], ['**מי קורא לו**', 'ה-CLI, ה-CI/CD pipeline שלך', 'האפליקציה שלך, בכל הודעה של משתמש']] } },
        { t: 'note', kind: 'tip', en: 'This split exists in most AWS services, and it matters for security: the role of your application needs only the data plane permission `bedrock-agentcore:InvokeAgentRuntime`. It should not be able to create or delete runtimes.', he: 'הפיצול הזה קיים ברוב שירותי AWS, והוא חשוב לאבטחה: ה-role של האפליקציה שלך צריך רק את הרשאת ה-data plane שנקראת `bedrock-agentcore:InvokeAgentRuntime`. הוא לא אמור להיות מסוגל ליצור או למחוק runtimes.' },
        { t: 'code', lang: 'python', code: 'import boto3, json, uuid\n\nclient = boto3.client("bedrock-agentcore")           # data plane client\nsession_id = str(uuid.uuid4())                       # one per conversation; keep it and reuse it\n\nresponse = client.invoke_agent_runtime(\n    agentRuntimeArn=agent_arn,\n    runtimeSessionId=session_id,                     # at least 33 characters\n    payload=json.dumps({"prompt": "Hello"}).encode(),\n    # qualifier="DEFAULT"                            # endpoint name (optional)\n)\n\nif "text/event-stream" in response.get("contentType", ""):\n    for line in response["response"].iter_lines(chunk_size=10):\n        if line and line.decode().startswith("data: "):\n            print(line.decode()[6:])                 # one streamed piece\nelif response.get("contentType") == "application/json":\n    print(json.loads(b"".join(response["response"]).decode()))', caption: { en: 'The payload is bytes of whatever JSON your entrypoint expects. The answer is a stream (SSE) or one JSON, depending on whether your entrypoint yields or returns.', he: 'ה-payload הוא bytes של ה-JSON שה-entrypoint שלך מצפה לו, מה שהוא לא יהיה. התשובה היא stream (SSE) או JSON אחד, תלוי אם ה-entrypoint שלך עושה yield או return.' } },
        { t: 'fill', prompt: { en: 'Call the agent on its `prod` endpoint, in an existing conversation.', he: 'קרא לסוכן ב-endpoint בשם `prod` שלו, בתוך שיחה קיימת.' }, lang: 'python',
          code: 'client = boto3.client("{{1}}")\n\nresponse = client.{{2}}(\n    agentRuntimeArn=agent_arn,\n    {{3}}=session_id,\n    payload=json.dumps({"prompt": "And the second one?"}).encode(),\n    {{4}}="prod",\n)',
          blanks: [ { accept: ['bedrock-agentcore'], hint: { en: 'the data plane client, without "-control"', he: 'ה-client של ה-data plane, בלי "-control"' } }, { accept: ['invoke_agent_runtime'], hint: { en: 'InvokeAgentRuntime in snake_case', he: 'InvokeAgentRuntime ב-snake_case' } }, { accept: ['runtimeSessionId'], hint: { en: 'camelCase: runtime + Session + Id', he: 'camelCase: runtime + Session + Id' } }, { accept: ['qualifier'], hint: { en: 'the parameter that names the endpoint', he: 'הפרמטר שנותן את שם ה-endpoint' } } ],
          explain: { en: 'Same session ID = same microVM = the agent still has the earlier turns in memory. The qualifier chooses which endpoint, and so which version, answers.', he: 'אותו session ID = אותו microVM = הסוכן עדיין מחזיק בזיכרון את התורות הקודמים. ה-qualifier בוחר איזה endpoint, וכך איזה version, עונה.' } },
        { t: 'quiz', q: { en: 'Your web backend must send user messages to the agent. Which boto3 client and method?', he: 'ה-backend של ה-web שלך צריך לשלוח הודעות משתמשים לסוכן. איזה boto3 client ואיזו מתודה?' },
          options: { en: ['`bedrock-runtime` and `converse`', '`bedrock-agentcore-control` and `create_agent_runtime`', '`bedrock-agent-runtime` and `invoke_agent`', '`bedrock-agentcore` and `invoke_agent_runtime`'], he: ['`bedrock-runtime` ו-`converse`', '`bedrock-agentcore-control` ו-`create_agent_runtime`', '`bedrock-agent-runtime` ו-`invoke_agent`', '`bedrock-agentcore` ו-`invoke_agent_runtime`'] },
          answer: 3, explain: { en: 'Invoking is a data plane call. `bedrock-runtime.converse` calls a model directly, with no agent. `bedrock-agent-runtime.invoke_agent` belongs to the old Bedrock Agents Classic. The names are easy to mix up, so learn them once.', he: 'הפעלה היא קריאת data plane. `bedrock-runtime.converse` קורא ישירות למודל, בלי סוכן. `bedrock-agent-runtime.invoke_agent` שייך ל-Bedrock Agents Classic הישן. קל לבלבל בין השמות, אז לומדים אותם פעם אחת.' } },
        { t: 'h', en: 'Session IDs: small detail, big consequences', he: 'Session IDs: פרט קטן, השלכות גדולות' },
        { t: 'list', en: ['The ID must be **at least 33 characters**. A UUID (36 characters) is the normal choice.', '**One ID per conversation.** Create it when the conversation starts, store it with the conversation, send it on every turn.', '**Never share an ID between users.** The ID decides which microVM answers. Two users on one ID would share one environment and one history.', 'Do not build it only from something guessable or permanent like the user ID: the same user can have many conversations, and each needs its own session.', 'If you send no ID, the service generates one. Then you must read it from the response and reuse it, or every message starts a new session.'], he: ['ה-ID חייב להיות **לפחות 33 תווים**. UUID (36 תווים) הוא הבחירה הרגילה.', '**ID אחד לכל שיחה.** יוצרים אותו כשהשיחה מתחילה, שומרים אותו יחד עם השיחה, ושולחים אותו בכל תור.', '**אף פעם לא חולקים ID בין משתמשים.** ה-ID קובע איזה microVM עונה. שני משתמשים על ID אחד יחלקו סביבה אחת והיסטוריה אחת.', 'לא בונים אותו רק ממשהו שאפשר לנחש או ממשהו קבוע כמו מזהה המשתמש: לאותו משתמש יכולות להיות הרבה שיחות, וכל אחת צריכה session משלה.', 'אם לא שולחים ID, השירות מייצר אחד. אז חייבים לקרוא אותו מהתשובה ולהשתמש בו שוב, אחרת כל הודעה מתחילה session חדש.'] },
        { t: 'quiz', q: { en: 'A developer hard-coded one session ID constant in the backend "to keep it simple". All users go through it. What is the worst result?', he: 'מפתח קבע בקוד של ה-backend קבוע אחד של session ID "כדי שיהיה פשוט". כל המשתמשים עוברים דרכו. מה התוצאה הכי גרועה?' },
          options: { en: ['Every request is slower', 'The bill is a little higher', 'All users share one microVM and one conversation state: user A can get answers based on the data of user B', 'Runtime rejects the second user'], he: ['כל בקשה איטית יותר', 'החשבון קצת יותר גבוה', 'כל המשתמשים חולקים microVM אחד ו-state של שיחה אחת: משתמש A יכול לקבל תשובות שמבוססות על המידע של משתמש B', 'Runtime דוחה את המשתמש השני'] },
          answer: 2, explain: { en: 'Session isolation protects sessions from each other. It cannot protect users that you put into the same session. This is a data leak that you built yourself.', he: 'Session isolation מגן על sessions זה מפני זה. הוא לא יכול להגן על משתמשים ששמת באותו session. זו דליפת מידע שבנית בעצמך.' } },
        { t: 'quiz', q: { en: 'A developer uses `runtimeSessionId="user-42"`. The call is rejected. Why?', he: 'מפתח משתמש ב-`runtimeSessionId="user-42"`. הקריאה נדחית. למה?' },
          options: { en: ['Session IDs may contain only digits', 'The session must be created first with a control plane call', 'The ID is too short: it must be at least 33 characters, so use a UUID', 'Hyphens are not allowed in session IDs'], he: ['Session IDs יכולים להכיל רק ספרות', 'חייבים קודם ליצור את ה-session עם קריאת control plane', 'ה-ID קצר מדי: הוא חייב להיות לפחות 33 תווים, אז משתמשים ב-UUID', 'אסור מקפים ב-session IDs'] },
          answer: 2, explain: { en: 'There is no "create session" call: the first invoke with a new ID creates the session. But the ID has a minimum length of 33 characters. A UUID has hyphens and is fine.', he: 'אין קריאת "create session": ה-invoke הראשון עם ID חדש יוצר את ה-session. אבל ל-ID יש אורך מינימלי של 33 תווים. ב-UUID יש מקפים והוא בסדר גמור.' } },
        { t: 'h', en: 'Limits that shape your design', he: 'גבולות שמעצבים את התכנון שלך' },
        { t: 'table', head: { en: ['Limit', 'Value'], he: ['גבול', 'ערך'] }, rows: {
          en: [['A synchronous request', '15 minutes'], ['A streaming response (SSE or WebSocket)', '60 minutes'], ['Request or response payload', '100 MB'], ['One streaming chunk', '10 MB'], ['One WebSocket frame', '64 KB']],
          he: [['בקשה סינכרונית', '15 דקות'], ['תשובת streaming (SSE או WebSocket)', '60 דקות'], ['payload של בקשה או תשובה', '100 MB'], ['chunk אחד ב-streaming', '10 MB'], ['frame אחד ב-WebSocket', '64 KB']] } },
        { t: 'h', en: 'Long-running work', he: 'עבודה ארוכה' },
        { t: 'p', en: 'Some jobs take an hour: analyze 2,000 documents, run a long research task. You cannot hold one request open for that. The pattern: the entrypoint **starts** the work in the background and returns at once. While the work runs, `/ping` reports [[HealthyBusy]], so the session is not terminated as idle. The SDK does the ping part for you:', he: 'יש עבודות שלוקחות שעה: לנתח 2,000 מסמכים, להריץ משימת מחקר ארוכה. אי אפשר להחזיק בקשה אחת פתוחה בשביל זה. הדפוס: ה-entrypoint **מתחיל** את העבודה ברקע וחוזר מיד. בזמן שהעבודה רצה, `/ping` מדווח [[HealthyBusy]], כך שה-session לא מסתיים כ-idle. ה-SDK עושה בשבילך את החלק של ה-ping:' },
        { t: 'code', lang: 'python', code: 'task_id = app.add_async_task("data_processing")   # ping becomes HealthyBusy\n# ... do the work in a background thread ...\napp.complete_async_task(task_id)                  # ping returns to Healthy', caption: { en: 'The work itself runs in a background thread that you start. The result should go somewhere durable (a database, S3, Memory), and the app asks for it later with another request.', he: 'העבודה עצמה רצה ב-thread ברקע שאתה מפעיל. את התוצאה כדאי לשים במקום קבוע (מסד נתונים, S3, Memory), והאפליקציה מבקשת אותה אחר כך בבקשה נוספת.' } },
        { t: 'note', kind: 'warn', en: '**Do not block inside the entrypoint.** If one thread is stuck in a long job, it also cannot answer `/ping`. Runtime then sees a silent session and terminates it after the idle timeout, in the middle of your job. A session that reports `HealthyBusy` stays alive up to the max lifetime: 8 hours on microVMs.', he: '**לא חוסמים בתוך ה-entrypoint.** אם thread אחד תקוע בעבודה ארוכה, הוא גם לא יכול לענות ל-`/ping`. Runtime רואה אז session שותק ומסיים אותו אחרי ה-idle timeout, באמצע העבודה שלך. session שמדווח `HealthyBusy` נשאר חי עד ה-max lifetime: 8 שעות על microVMs.' },
        { t: 'fill', prompt: { en: 'Mark the start and the end of a background task so that the session is kept alive.', he: 'סמן את ההתחלה ואת הסוף של משימת רקע כדי שה-session יישאר חי.' }, lang: 'python',
          code: '@app.entrypoint\ndef handler(payload):\n    task_id = app.{{1}}("build_report")\n    threading.Thread(target=build_report, args=(payload, task_id)).start()\n    return {"status": "started"}\n\ndef build_report(payload, task_id):\n    ...                                  # an hour of work\n    app.{{2}}(task_id)',
          blanks: [ { accept: ['add_async_task'], hint: { en: 'add + async + task', he: 'add + async + task' } }, { accept: ['complete_async_task'], hint: { en: 'complete + async + task', he: 'complete + async + task' } } ],
          explain: { en: 'The entrypoint returns in milliseconds. Between the two calls, `/ping` answers `HealthyBusy`. If you forget the second call, the session never looks idle and you pay for it until the max lifetime.', he: 'ה-entrypoint חוזר תוך אלפיות שנייה. בין שתי הקריאות, `/ping` עונה `HealthyBusy`. אם שוכחים את הקריאה השנייה, ה-session אף פעם לא נראה idle ומשלמים עליו עד ה-max lifetime.' } },
        { t: 'quiz', q: { en: 'A "weekly report" request makes the agent work for about two hours. Today it is one synchronous `InvokeAgentRuntime` call, and it always fails. What is the right design?', he: 'בקשת "דוח שבועי" גורמת לסוכן לעבוד בערך שעתיים. היום זו קריאת `InvokeAgentRuntime` סינכרונית אחת, והיא תמיד נכשלת. מה התכנון הנכון?' },
          options: { en: ['Raise the client timeout to three hours', 'Start the work as a background task, return at once, and let the app fetch the result later', 'Send a larger payload', 'Use a session ID with more characters'], he: ['להעלות את ה-timeout של ה-client לשלוש שעות', 'להתחיל את העבודה כמשימת רקע, לחזור מיד, ולתת לאפליקציה להביא את התוצאה אחר כך', 'לשלוח payload גדול יותר', 'להשתמש ב-session ID עם יותר תווים'] },
          answer: 1, explain: { en: 'A synchronous request ends after 15 minutes, and even a stream ends after 60. The limit is on the service side, so a client timeout does not help. Background work can run up to 8 hours on microVMs.', he: 'בקשה סינכרונית מסתיימת אחרי 15 דקות, ואפילו stream מסתיים אחרי 60. הגבול הוא בצד של השירות, אז timeout של ה-client לא עוזר. עבודת רקע יכולה לרוץ עד 8 שעות על microVMs.' } },
        { t: 'h', en: 'Versions and endpoints: releasing safely', he: 'Versions ו-endpoints: לשחרר בבטחה' },
        { t: 'p', en: 'Every runtime has [[Version]]s. Version 1 is created with the runtime. Each update (a new image, another protocol, new network settings) creates a new version, and old versions never change. An [[Endpoint]] is a name that points to one version. The `DEFAULT` endpoint is created for you and **always follows the newest version**. You can add your own endpoints, such as `prod`, with `CreateAgentRuntimeEndpoint`, up to 10 per agent. The caller picks an endpoint with the [[Qualifier]].', he: 'לכל runtime יש [[Version]]s. Version 1 נוצר יחד עם ה-runtime. כל עדכון (image חדש, פרוטוקול אחר, הגדרות רשת חדשות) יוצר version חדש, ו-versions ישנים לא משתנים לעולם. [[Endpoint]] הוא שם שמצביע על version אחד. ה-endpoint בשם `DEFAULT` נוצר בשבילך ו**תמיד עוקב אחרי ה-version החדש ביותר**. אפשר להוסיף endpoints משלך, כמו `prod`, עם `CreateAgentRuntimeEndpoint`, עד 10 לכל סוכן. הקורא בוחר endpoint עם ה-[[Qualifier]].' },
        { t: 'flow', steps: { en: ['Deploy: version 7 is created', 'DEFAULT now points to version 7', 'Test version 7 through DEFAULT', 'Move the prod endpoint from 6 to 7', 'Problem? Point prod back to 6'], he: ['Deploy: נוצר version 7', 'DEFAULT מצביע עכשיו על version 7', 'בודקים את version 7 דרך DEFAULT', 'מעבירים את ה-endpoint בשם prod מ-6 ל-7', 'בעיה? מחזירים את prod ל-6'] }, caption: { en: 'Moving an endpoint is the `UpdateAgentRuntimeEndpoint` operation. A rollback is the same operation in the other direction.', he: 'העברה של endpoint היא הפעולה `UpdateAgentRuntimeEndpoint`. rollback הוא אותה פעולה בכיוון ההפוך.' } },
        { t: 'quiz', q: { en: 'On Friday a developer deployed an experiment. Seconds later production users got the experimental agent. The app calls `invoke_agent_runtime` without a qualifier. What went wrong, and what is the fix?', he: 'ביום שישי מפתח עשה deploy לניסוי. שניות אחר כך משתמשי הפרודקשן קיבלו את הסוכן הניסיוני. האפליקציה קוראת ל-`invoke_agent_runtime` בלי qualifier. מה השתבש, ומה התיקון?' },
          options: { en: ['The app used the DEFAULT endpoint, which follows the newest version; create a `prod` endpoint pinned to a tested version and pass it as the qualifier', 'The session IDs were reused; create new ones', 'The idle timeout was too short; raise it', 'The deploy used the wrong Region; redeploy'], he: ['האפליקציה השתמשה ב-endpoint בשם DEFAULT, שעוקב אחרי ה-version החדש ביותר; יוצרים endpoint בשם `prod` שמקובע ל-version שנבדק ומעבירים אותו כ-qualifier', 'ה-session IDs היו בשימוש חוזר; יוצרים חדשים', 'ה-idle timeout היה קצר מדי; מעלים אותו', 'ה-deploy השתמש ב-Region לא נכון; עושים deploy מחדש'] },
          answer: 0, explain: { en: '`DEFAULT` is useful for development because it always shows the newest version. For exactly that reason, production traffic should go through a named endpoint that moves only when you decide.', he: '`DEFAULT` שימושי לפיתוח כי הוא תמיד מציג את ה-version החדש ביותר. בדיוק מהסיבה הזו, תעבורת פרודקשן צריכה לעבור דרך endpoint עם שם שזז רק כשאתה מחליט.' } },
        { t: 'note', kind: 'tip', en: 'Two more data plane operations worth knowing: `StopRuntimeSession` ends a session now instead of waiting for the idle timeout (you stop paying for its memory), and `RetryableConflictException` (HTTP 409) is a temporary "session operation in progress" error that the SDKs retry for you.', he: 'עוד שתי פעולות data plane ששווה להכיר: `StopRuntimeSession` מסיימת session עכשיו במקום לחכות ל-idle timeout (מפסיקים לשלם על הזיכרון שלו), ו-`RetryableConflictException` (HTTP 409) היא שגיאה זמנית של "session operation in progress" שה-SDKs עושים לה retry בשבילך.' },
        { t: 'reveal', q: { en: 'Interview question: "How would you release a new version of an agent without risk to production users?"', he: 'שאלת ראיון: "איך היית משחרר גרסה חדשה של סוכן בלי סיכון למשתמשי הפרודקשן?"' },
          a: { en: 'I never let production call the DEFAULT endpoint, because DEFAULT follows every new version. Production calls a named endpoint, for example `prod`, that is pinned to a version. A deploy creates a new immutable version, and DEFAULT moves to it. I test it there, by hand and with evaluations. When it passes, I update the `prod` endpoint to the new version. If metrics or user feedback get worse, I point `prod` back to the previous version, which still exists unchanged. For more safety I can keep a `staging` endpoint in between, since an agent can have up to 10 endpoints.', he: 'אני אף פעם לא נותן לפרודקשן לקרוא ל-endpoint בשם DEFAULT, כי DEFAULT עוקב אחרי כל version חדש. הפרודקשן קורא ל-endpoint עם שם, לדוגמה `prod`, שמקובע ל-version. deploy יוצר version חדש שלא משתנה, ו-DEFAULT עובר אליו. אני בודק אותו שם, ידנית ועם evaluations. כשהוא עובר, אני מעדכן את ה-endpoint בשם `prod` ל-version החדש. אם המדדים או המשוב מהמשתמשים מחמירים, אני מחזיר את `prod` ל-version הקודם, שעדיין קיים בלי שינוי. בשביל עוד ביטחון אפשר להחזיק באמצע endpoint בשם `staging`, כי לסוכן יכולים להיות עד 10 endpoints.' } }
      ]
    },
    {
      id: 'm07l5', minutes: 15,
      title: { en: 'Security, networking, pricing, quotas and debugging', he: 'אבטחה, רשת, תמחור, quotas ודיבוג' },
      blocks: [
        { t: 'h', en: 'Who may call the agent: inbound auth', he: 'מי רשאי לקרוא לסוכן: inbound auth' },
        { t: 'p', en: 'Runtime checks the caller **before** your code runs. That check is the [[Inbound auth]]. A runtime uses one of two methods, never both:', he: 'Runtime בודק את הקורא **לפני** שהקוד שלך רץ. הבדיקה הזו היא ה-[[Inbound auth]]. runtime משתמש באחת משתי שיטות, אף פעם לא בשתיהן:' },
        { t: 'table', head: { en: ['', 'IAM [[SigV4]] (default)', '[[JWT]] bearer token'], he: ['', 'IAM [[SigV4]] (ברירת מחדל)', '[[JWT]] bearer token'] }, rows: {
          en: [['**The caller is**', 'An AWS identity: your backend, a Lambda function, another AWS service', 'A user who signed in with an identity provider (Cognito, Okta, Entra ID…)'], ['**How it calls**', 'The AWS SDK signs the request', 'A plain HTTPS request with `Authorization: Bearer <token>`. The AWS SDK **cannot** be used.'], ['**What you configure**', 'An IAM policy that allows `bedrock-agentcore:InvokeAgentRuntime`', 'Discovery URL, allowed audiences, allowed clients, allowed scopes, required custom claims'], ['**No valid identity**', 'HTTP 403', 'HTTP 401']],
          he: [['**הקורא הוא**', 'זהות של AWS: ה-backend שלך, פונקציית Lambda, שירות AWS אחר', 'משתמש שהזדהה מול ספק זהויות (Cognito, Okta, Entra ID…)'], ['**איך הוא קורא**', 'ה-SDK של AWS חותם על הבקשה', 'בקשת HTTPS רגילה עם `Authorization: Bearer <token>`. **אי אפשר** להשתמש ב-SDK של AWS.'], ['**מה מגדירים**', 'IAM policy שמתיר `bedrock-agentcore:InvokeAgentRuntime`', 'Discovery URL, allowed audiences, allowed clients, allowed scopes, required custom claims'], ['**בלי זהות תקפה**', 'HTTP 403', 'HTTP 401']] } },
        { t: 'code', lang: 'bash', code: 'ESCAPED_AGENT_ARN=$(echo -n "$AGENT_ARN" | jq -sRr \'@uri\')\ncurl -X POST "https://bedrock-agentcore.us-east-1.amazonaws.com/runtimes/${ESCAPED_AGENT_ARN}/invocations?qualifier=DEFAULT" \\\n  -H "Authorization: Bearer ${TOKEN}" \\\n  -H "Content-Type: application/json" \\\n  -H "X-Amzn-Bedrock-AgentCore-Runtime-Session-Id: ${SESSION_ID}" \\\n  -d \'{"prompt": "hello what is 1+1?"}\'', caption: { en: 'Calling a runtime that uses JWT auth. The ARN goes into the URL (URL-encoded), and the session ID goes into a header.', he: 'קריאה ל-runtime שמשתמש ב-JWT auth. ה-ARN נכנס ל-URL (מקודד ל-URL), וה-session ID נכנס ל-header.' } },
        { t: 'console', service: 'Amazon Bedrock AgentCore', nav: ['Agents', '#Resources', 'Gateways', 'Observability'], active: 'Agents',
          crumbs: ['Amazon Bedrock AgentCore', 'Agents', 'Create Host agent (runtime)'],
          heading: 'Inbound auth',
          panels: [ { title: 'JWT configuration', desc: 'Runtime validates every token against these settings before your code runs.', fields: [
            { label: 'Discovery URL', type: 'input', value: 'https://idp.example.com/.well-known/openid-configuration', n: 1 },
            { label: 'Allowed audiences', type: 'input', value: 'support-api', n: 2 },
            { label: 'Allowed clients', type: 'input', value: 'support-web', n: 3 },
            { label: 'Allowed scopes', type: 'input', value: 'agent:invoke', n: 4 },
            { label: 'Required custom claims', type: 'input', value: 'department = support', n: 5 } ] } ],
          callouts: [
            { n: 1, en: 'Where Runtime finds the public keys of your identity provider. It must end in /.well-known/openid-configuration (or oauth-authorization-server).', he: 'איפה Runtime מוצא את המפתחות הציבוריים של ספק הזהויות שלך. חייב להסתיים ב-/.well-known/openid-configuration (או oauth-authorization-server).' },
            { n: 2, en: 'The token must be issued for this audience: the `aud` claim.', he: 'הטוקן חייב להיות מונפק לקהל הזה: ה-claim בשם `aud`.' },
            { n: 3, en: 'Which applications may call: the `client_id` claim.', he: 'אילו אפליקציות רשאיות לקרוא: ה-claim בשם `client_id`.' },
            { n: 4, en: 'The token must carry one of these scopes.', he: 'הטוקן חייב לשאת אחד מה-scopes האלה.' },
            { n: 5, en: 'Extra conditions on the claims inside the token.', he: 'תנאים נוספים על ה-claims שבתוך הטוקן.' } ],
          caption: { en: 'Simplified. The five field names are the JWT settings that the AWS docs list for Runtime inbound auth (November 2026); the values and the layout are an illustration.', he: 'מפושט. חמשת שמות השדות הם הגדרות ה-JWT שהתיעוד של AWS מפרט ל-inbound auth של Runtime (נובמבר 2026); הערכים והפריסה הם המחשה.' } },
        { t: 'quiz', q: { en: 'A runtime was created with JWT inbound auth. A developer calls it with `boto3.client("bedrock-agentcore").invoke_agent_runtime(...)`, and it is rejected. Why?', he: 'runtime נוצר עם JWT inbound auth. מפתח קורא לו עם `boto3.client("bedrock-agentcore").invoke_agent_runtime(...)`, והקריאה נדחית. למה?' },
          options: { en: ['boto3 is too old', 'The session ID must go into the payload', 'JWT runtimes accept only WebSocket connections', 'With JWT auth you cannot use the AWS SDK: send an HTTPS request with the bearer token'], he: ['boto3 ישן מדי', 'ה-session ID חייב להיכנס ל-payload', 'runtimes עם JWT מקבלים רק חיבורי WebSocket', 'עם JWT auth אי אפשר להשתמש ב-SDK של AWS: שולחים בקשת HTTPS עם ה-bearer token'] },
          answer: 3, explain: { en: 'boto3 signs with SigV4, and a runtime accepts SigV4 **or** JWT, not both. Decide early who your callers are: AWS identities (SigV4) or signed-in users (JWT).', he: 'boto3 חותם עם SigV4, ו-runtime מקבל SigV4 **או** JWT, לא את שניהם. מחליטים מוקדם מי הקוראים שלך: זהויות של AWS (SigV4) או משתמשים שהזדהו (JWT).' } },
        { t: 'h3', en: 'Knowing the end user', he: 'לדעת מי משתמש הקצה' },
        { t: 'list', en: ['With JWT: allowlist the `Authorization` header for the runtime, and your code can read the token of the caller from `context.request_headers`.', 'With SigV4: the backend can pass a user ID in the header `X-Amzn-Bedrock-AgentCore-Runtime-User-Id`. This needs the extra IAM action `bedrock-agentcore:InvokeAgentRuntimeForUser`. Runtime does not verify that value, so allow only trusted backends to send it.'], he: ['עם JWT: מוסיפים את ה-header בשם `Authorization` ל-allowlist של ה-runtime, והקוד שלך יכול לקרוא את הטוקן של הקורא מתוך `context.request_headers`.', 'עם SigV4: ה-backend יכול להעביר מזהה משתמש ב-header בשם `X-Amzn-Bedrock-AgentCore-Runtime-User-Id`. זה דורש את פעולת ה-IAM הנוספת `bedrock-agentcore:InvokeAgentRuntimeForUser`. Runtime לא מאמת את הערך הזה, אז מרשים רק ל-backends מהימנים לשלוח אותו.'] },
        { t: 'h', en: 'What the agent may do: the execution role', he: 'מה הסוכן רשאי לעשות: ה-execution role' },
        { t: 'p', en: 'Inbound auth is about who comes **in**. The [[Execution role]] is about what the agent can reach going **out**. It is an IAM role that the runtime assumes (the service principal is `bedrock-agentcore.amazonaws.com`). Every AWS call from your agent code uses it: calling a Bedrock model, reading from S3, writing logs. People mix up the two roles all the time:', he: 'Inbound auth עוסק במי **נכנס**. ה-[[Execution role]] עוסק במה שהסוכן יכול להגיע אליו **החוצה**. זה IAM role שה-runtime מקבל על עצמו (ה-service principal הוא `bedrock-agentcore.amazonaws.com`). כל קריאה ל-AWS מקוד הסוכן שלך משתמשת בו: קריאה למודל ב-Bedrock, קריאה מ-S3, כתיבת לוגים. אנשים מבלבלים בין שני ה-roles כל הזמן:' },
        { t: 'table', head: { en: ['', 'Role of the caller', 'Execution role'], he: ['', 'ה-role של הקורא', 'Execution role'] }, rows: {
          en: [['**Who has it**', 'Your backend or user', 'The runtime itself'], ['**Needs**', '`bedrock-agentcore:InvokeAgentRuntime`', 'Permission for what the agent code does: invoke models, pull the image, write logs, call your services'], ['**Typical mistake**', 'Giving it control plane rights', 'Giving it admin rights "to make it work"']],
          he: [['**למי יש אותו**', 'ל-backend או למשתמש שלך', 'ל-runtime עצמו'], ['**צריך**', '`bedrock-agentcore:InvokeAgentRuntime`', 'הרשאה למה שקוד הסוכן עושה: להפעיל מודלים, למשוך את ה-image, לכתוב לוגים, לקרוא לשירותים שלך'], ['**טעות טיפוסית**', 'לתת לו הרשאות control plane', 'לתת לו הרשאות admin "כדי שזה יעבוד"']] } },
        { t: 'quiz', q: { en: 'Invoking the agent works, but every answer is an error: the logs show `AccessDeniedException` when the agent code calls the Bedrock model. The caller has full Bedrock permissions. What do you fix?', he: 'ההפעלה של הסוכן עובדת, אבל כל תשובה היא שגיאה: הלוגים מראים `AccessDeniedException` כשקוד הסוכן קורא למודל ב-Bedrock. לקורא יש הרשאות Bedrock מלאות. מה מתקנים?' },
          options: { en: ['The IAM policy of the caller', 'The inbound auth settings', 'The execution role of the runtime: it needs permission to invoke the model', 'The session ID'], he: ['את ה-IAM policy של הקורא', 'את הגדרות ה-inbound auth', 'את ה-execution role של ה-runtime: הוא צריך הרשאה להפעיל את המודל', 'את ה-session ID'] },
          answer: 2, explain: { en: 'The call to the model is made by the agent, with the execution role. The permissions of the caller do not flow through. This is good: an agent with a prompt injection can only do what its own role allows, so keep that role small.', he: 'את הקריאה למודל עושה הסוכן, עם ה-execution role. ההרשאות של הקורא לא עוברות הלאה. זה טוב: סוכן שעבר prompt injection יכול לעשות רק את מה שה-role שלו מתיר, אז שומרים על ה-role הזה קטן.' } },
        { t: 'h', en: 'Networking: PUBLIC or VPC', he: 'רשת: PUBLIC או VPC' },
        { t: 'p', en: 'By default the network mode is `PUBLIC`: the agent can reach the internet and public AWS endpoints. If the agent must reach **private** resources, such as an internal database, you choose mode `VPC` and give subnets and security groups. AWS then creates network interfaces in your [[VPC]] for the agent.', he: 'כברירת מחדל מצב הרשת הוא `PUBLIC`: הסוכן יכול להגיע לאינטרנט ול-endpoints ציבוריים של AWS. אם הסוכן חייב להגיע למשאבים **פרטיים**, כמו מסד נתונים פנימי, בוחרים במצב `VPC` ונותנים subnets ו-security groups. AWS יוצרת אז ממשקי רשת ב-[[VPC]] שלך בשביל הסוכן.' },
        { t: 'code', lang: 'python', code: 'networkConfiguration = {\n    "networkMode": "VPC",\n    "networkModeConfig": {"subnets": ["subnet-..."], "securityGroups": ["sg-..."]},\n}', caption: { en: 'The default is `{"networkMode": "PUBLIC"}`.', he: 'ברירת המחדל היא `{"networkMode": "PUBLIC"}`.' } },
        { t: 'note', kind: 'warn', en: '**The classic VPC trap: putting the agent in a public subnet does not give it internet access.** Use private subnets with a NAT gateway for the internet, and add VPC endpoints for the AWS services the agent needs to start and to log: ECR (`ecr.dkr`, `ecr.api`), S3 (a gateway endpoint) and CloudWatch Logs. Also, only some Availability Zones are supported in each Region; check the docs for the list.', he: '**המלכודת הקלאסית של VPC: לשים את הסוכן ב-public subnet לא נותן לו גישה לאינטרנט.** משתמשים ב-private subnets עם NAT gateway בשביל האינטרנט, ומוסיפים VPC endpoints לשירותי AWS שהסוכן צריך כדי לעלות ולכתוב לוגים: ECR (`ecr.dkr`, `ecr.api`), S3 (gateway endpoint) ו-CloudWatch Logs. בנוסף, רק חלק מה-Availability Zones נתמכים בכל Region; בודקים בתיעוד את הרשימה.' },
        { t: 'quiz', q: { en: 'You moved the runtime into your VPC, in a public subnet, so that it can reach the internal database. Now it cannot call an external API. What is the fix?', he: 'העברת את ה-runtime לתוך ה-VPC שלך, ב-public subnet, כדי שיוכל להגיע למסד הנתונים הפנימי. עכשיו הוא לא מצליח לקרוא ל-API חיצוני. מה התיקון?' },
          options: { en: ['Use private subnets with a NAT gateway, plus VPC endpoints for ECR, S3 and CloudWatch Logs', 'Give the runtime a public IP address', 'Change the protocol to MCP', 'Raise the idle timeout'], he: ['להשתמש ב-private subnets עם NAT gateway, ועוד VPC endpoints ל-ECR, S3 ו-CloudWatch Logs', 'לתת ל-runtime כתובת IP ציבורית', 'לשנות את הפרוטוקול ל-MCP', 'להעלות את ה-idle timeout'] },
          answer: 0, explain: { en: 'For Runtime, a public subnet does not mean internet access. Outbound traffic needs a NAT gateway, and the traffic to AWS services should go through VPC endpoints.', he: 'ב-Runtime, public subnet לא אומר גישה לאינטרנט. תעבורה יוצאת צריכה NAT gateway, והתעבורה לשירותי AWS צריכה לעבור דרך VPC endpoints.' } },
        { t: 'h', en: 'Platform versions and compute types (overview)', he: 'Platform versions וסוגי compute (סקירה)' },
        { t: 'table', head: { en: ['Choice', 'What it is', 'When you care'], he: ['בחירה', 'מה זה', 'מתי זה חשוב לך'] }, rows: {
          en: [['[[Platform version]] **V1**', 'The default way to start sessions.', 'Fine to begin with.'], ['Platform version **V2**', 'Starts each session by restoring a **snapshot** of your already initialized environment. Reclaims idle memory. Images up to 10 GB. Create and update take minutes, and the container must report healthy on `/ping` within 120 seconds.', 'Your agent has a slow start (big imports, big image) and you want fast, consistent [[Cold start]]s.'], ['Compute type **microVMs**', 'The default: one microVM per session.', 'Almost always.'], ['Compute type **[[Instances]]**', 'Managed EC2 machines in your account. GPUs. Sessions up to 14 days.', 'You need a GPU, or sessions longer than 8 hours.']],
          he: [['[[Platform version]] **V1**', 'הדרך ברירת המחדל להעלות sessions.', 'בסדר להתחלה.'], ['Platform version **V2**', 'מעלה כל session על ידי שחזור **snapshot** של הסביבה שלך אחרי שכבר אותחלה. מחזיר זיכרון לא בשימוש. images של עד 10 GB. יצירה ועדכון לוקחים דקות, וה-container חייב לדווח healthy ב-`/ping` תוך 120 שניות.', 'לסוכן שלך יש עלייה איטית (imports גדולים, image גדול) ואתה רוצה [[Cold start]]s מהירים ועקביים.'], ['סוג compute **microVMs**', 'ברירת המחדל: microVM אחד לכל session.', 'כמעט תמיד.'], ['סוג compute **[[Instances]]**', 'מכונות EC2 מנוהלות בחשבון שלך. GPUs. Sessions של עד 14 ימים.', 'צריך GPU, או sessions ארוכים מ-8 שעות.']] } },
        { t: 'h', en: 'What you pay for', he: 'על מה משלמים' },
        { t: 'list', en: ['**microVMs**: vCPU-seconds of **active** CPU, plus GB-seconds of memory. Billed per second, no minimum fee per month.', '**Example prices from November 2026** (they change; check the pricing page): V1 is $0.0895 per vCPU-hour and $0.00945 per GB-hour. So one full minute of busy CPU on one vCPU costs about $0.0015.', '**V2** has its own rates, and a lower "committed baseline" rate if you set a resource configuration.', '**Instances**: the EC2 price plus an AgentCore management fee.', '**Not included**: model tokens (billed by Bedrock or your model provider), CloudWatch logs and traces, and other AgentCore services such as Memory or Gateway.'], he: ['**microVMs**: שניות vCPU של CPU **פעיל**, ועוד שניות GB של זיכרון. חיוב לפי שנייה, בלי תשלום מינימום חודשי.', '**מחירים לדוגמה מנובמבר 2026** (הם משתנים; בדוק בעמוד התמחור): V1 הוא $0.0895 לשעת vCPU ו-$0.00945 לשעת GB. כלומר דקה שלמה של CPU עסוק על vCPU אחד עולה בערך $0.0015.', 'ל-**V2** יש תעריפים משלו, ותעריף "committed baseline" נמוך יותר אם מגדירים resource configuration.', '**Instances**: המחיר של EC2 ועוד דמי ניהול של AgentCore.', '**לא כלול**: טוקנים של המודל (מחויבים על ידי Bedrock או ספק המודל שלך), לוגים ו-traces ב-CloudWatch, ושירותי AgentCore אחרים כמו Memory או Gateway.'] },
        { t: 'h', en: 'Quotas', he: 'Quotas' },
        { t: 'table', head: { en: ['Quota', 'Default'], he: ['Quota', 'ברירת מחדל'] }, rows: {
          en: [['Active sessions per account', '5,000 in us-east-1 and us-west-2; 2,500 in other Regions (adjustable)'], ['New sessions per second', '25 (adjustable)'], ['Data plane requests per second', '1,000, shared by `InvokeAgentRuntime`, `StopRuntimeSession` and the other data plane operations'], ['Agents per account', '1,000'], ['Versions per agent / endpoints per agent', '1,000 / 10'], ['Environment variables', '4 KB in total']],
          he: [['Sessions פעילים לחשבון', '5,000 ב-us-east-1 וב-us-west-2; 2,500 ב-Regions אחרים (ניתן לשינוי)'], ['Sessions חדשים בשנייה', '25 (ניתן לשינוי)'], ['בקשות data plane בשנייה', '1,000, משותף ל-`InvokeAgentRuntime`, ל-`StopRuntimeSession` ולשאר פעולות ה-data plane'], ['סוכנים לחשבון', '1,000'], ['Versions לסוכן / endpoints לסוכן', '1,000 / 10'], ['משתני סביבה', '4 KB בסך הכול']] } },
        { t: 'quiz', q: { en: 'A marketing campaign starts at 9:00. For a few seconds, about 40 new users per second open the chat. Some get HTTP 429. Existing conversations work fine. What is the likely cause?', he: 'קמפיין שיווקי מתחיל ב-9:00. למשך כמה שניות, בערך 40 משתמשים חדשים בשנייה פותחים את הצ׳אט. חלק מקבלים HTTP 429. שיחות קיימות עובדות טוב. מה הסיבה הסבירה?' },
          options: { en: ['The agent code has a bug', 'The execution role is missing a permission', 'The payload is larger than 100 MB', 'The quota for new sessions per second (25 by default) was passed; retry with backoff and ask for a higher quota'], he: ['יש באג בקוד הסוכן', 'ל-execution role חסרה הרשאה', 'ה-payload גדול מ-100 MB', 'עברו את ה-quota של sessions חדשים בשנייה (25 כברירת מחדל); עושים retry עם backoff ומבקשים quota גבוה יותר'] },
          answer: 3, explain: { en: '429 is [[Throttling]], not a bug in your agent. Only **new** sessions fail, which points to the session creation rate. The quota is adjustable, and your app should retry 429 with a growing delay anyway.', he: '429 הוא [[Throttling]], לא באג בסוכן שלך. רק sessions **חדשים** נכשלים, וזה מצביע על קצב יצירת ה-sessions. ה-quota ניתן לשינוי, ובכל מקרה האפליקציה שלך צריכה לעשות retry ל-429 עם השהיה הולכת וגדלה.' } },
        { t: 'h', en: 'Errors and how to debug them', he: 'שגיאות ואיך מדבגים אותן' },
        { t: 'p', en: 'Runtime returns normal HTTP status codes, with the error name in the header `x-amzn-ErrorType`. The first question is always: **is the problem on the way in, or inside my code?**', he: 'Runtime מחזיר קודי סטטוס רגילים של HTTP, עם שם השגיאה ב-header בשם `x-amzn-ErrorType`. השאלה הראשונה היא תמיד: **האם הבעיה בדרך פנימה, או בתוך הקוד שלי?**' },
        { t: 'table', head: { en: ['Code', 'Name', 'Usually means'], he: ['קוד', 'שם', 'בדרך כלל אומר'] }, rows: {
          en: [['400', 'ValidationException', 'A bad request, for example a session ID that is too short.'], ['401', 'UnauthorizedException', 'JWT runtime: the token is missing or not valid.'], ['403', 'AccessDeniedException', 'SigV4 runtime: the caller has no permission to invoke.'], ['404', 'ResourceNotFoundException', 'Wrong ARN, wrong Region, or an endpoint name that does not exist.'], ['409', 'ConflictException / RetryableConflictException', 'A session operation is in progress. The retryable one is temporary.'], ['**424**', '**RuntimeClientError**', '**Your container returned an error.** Runtime is fine; your code is not. Read the logs.'], ['429', 'ThrottlingException', 'You passed a rate quota. Retry with backoff.'], ['500', 'InternalServerException', 'A problem on the AWS side. Retry.']],
          he: [['400', 'ValidationException', 'בקשה לא תקינה, לדוגמה session ID קצר מדי.'], ['401', 'UnauthorizedException', 'runtime עם JWT: הטוקן חסר או לא תקף.'], ['403', 'AccessDeniedException', 'runtime עם SigV4: לקורא אין הרשאה להפעיל.'], ['404', 'ResourceNotFoundException', 'ARN שגוי, Region שגוי, או שם endpoint שלא קיים.'], ['409', 'ConflictException / RetryableConflictException', 'פעולה על ה-session נמצאת בתהליך. הגרסה ה-retryable היא זמנית.'], ['**424**', '**RuntimeClientError**', '**ה-container שלך החזיר שגיאה.** Runtime בסדר; הקוד שלך לא. קוראים את הלוגים.'], ['429', 'ThrottlingException', 'עברת quota של קצב. עושים retry עם backoff.'], ['500', 'InternalServerException', 'בעיה בצד של AWS. עושים retry.']] } },
        { t: 'list', en: ['**Logs**: `agentcore logs runtime --since 30m --level error`, or in CloudWatch the log group `/aws/bedrock-agentcore/runtimes/<agent_id>-<endpoint_name>`.', '**Traces**: `agentcore traces runtime list --since 30m` shows each request as steps: model calls and tool calls with their timing.', '**Metrics** in the CloudWatch namespace `AWS/Bedrock-AgentCore`: `Invocations`, `Throttles`, `System Errors`, `User Errors`, `Latency`, `ActiveSessionCount`.'], he: ['**Logs**: `agentcore logs runtime --since 30m --level error`, או ב-CloudWatch ה-log group בשם `/aws/bedrock-agentcore/runtimes/<agent_id>-<endpoint_name>`.', '**Traces**: `agentcore traces runtime list --since 30m` מציגה כל בקשה כצעדים: קריאות למודל וקריאות לכלים עם התזמון שלהן.', '**Metrics** ב-namespace של CloudWatch בשם `AWS/Bedrock-AgentCore`: `Invocations`, `Throttles`, `System Errors`, `User Errors`, `Latency`, `ActiveSessionCount`.'] },
        { t: 'quiz', q: { en: '`InvokeAgentRuntime` returns HTTP 424 with `RuntimeClientError`. Where do you look first?', he: '`InvokeAgentRuntime` מחזיר HTTP 424 עם `RuntimeClientError`. איפה מסתכלים קודם?' },
          options: { en: ['In the IAM policy of the caller', 'In the logs of your agent: your own container returned the error', 'In the service quotas', 'In the JWT settings'], he: ['ב-IAM policy של הקורא', 'בלוגים של הסוכן שלך: ה-container שלך הוא שהחזיר את השגיאה', 'ב-service quotas', 'בהגדרות ה-JWT'] },
          answer: 1, explain: { en: '424 means that the request passed auth and reached your code, and your code failed: an exception in the entrypoint, a missing dependency, a model call that was denied. IAM problems of the caller give 403, quotas give 429.', he: '424 אומר שהבקשה עברה את ה-auth והגיעה לקוד שלך, והקוד שלך נכשל: exception ב-entrypoint, תלות חסרה, קריאה למודל שנדחתה. בעיות IAM של הקורא נותנות 403, ו-quotas נותנות 429.' } },
        { t: 'match', prompt: { en: 'Match the status code to the first thing you check.', he: 'התאם את קוד הסטטוס לדבר הראשון שבודקים.' }, pairs: [
          { a: '401', b: { en: 'The bearer token and the JWT settings', he: 'ה-bearer token והגדרות ה-JWT' } },
          { a: '403', b: { en: 'The IAM permissions of the caller', he: 'הרשאות ה-IAM של הקורא' } },
          { a: '404', b: { en: 'The ARN, the Region and the endpoint name', he: 'ה-ARN, ה-Region ושם ה-endpoint' } },
          { a: '424', b: { en: 'The logs of your own agent code', he: 'הלוגים של קוד הסוכן שלך' } },
          { a: '429', b: { en: 'Your request rate against the quotas', he: 'קצב הבקשות שלך מול ה-quotas' } }
        ] },
        { t: 'reveal', q: { en: 'Interview question: "Explain the difference between inbound auth and the execution role of an agent on Runtime."', he: 'שאלת ראיון: "הסבר את ההבדל בין inbound auth ל-execution role של סוכן ב-Runtime."' },
          a: { en: 'They guard two different doors. Inbound auth is the front door: it decides who may call the agent. It is either IAM SigV4, for AWS identities such as my backend, or a JWT from an identity provider, for signed-in users, and Runtime checks it before my code runs. The execution role is the back door: it is the IAM role the runtime assumes, and it decides what my agent code may do in AWS, such as invoking a Bedrock model or reading a bucket. The permissions of the caller never pass through to the agent. I keep both small: callers get only the invoke permission, and the execution role gets only what the tools of the agent really need, because a tricked agent can do everything its role allows.', he: 'הם שומרים על שתי דלתות שונות. Inbound auth הוא הדלת הקדמית: הוא מחליט מי רשאי לקרוא לסוכן. זה או IAM SigV4, לזהויות של AWS כמו ה-backend שלי, או JWT מספק זהויות, למשתמשים שהזדהו, ו-Runtime בודק את זה לפני שהקוד שלי רץ. ה-execution role הוא הדלת האחורית: זה ה-IAM role שה-runtime מקבל על עצמו, והוא מחליט מה קוד הסוכן שלי רשאי לעשות ב-AWS, כמו להפעיל מודל ב-Bedrock או לקרוא מ-bucket. ההרשאות של הקורא אף פעם לא עוברות הלאה לסוכן. אני שומר על שניהם קטנים: קוראים מקבלים רק את הרשאת ה-invoke, וה-execution role מקבל רק את מה שהכלים של הסוכן באמת צריכים, כי סוכן שרימו אותו יכול לעשות כל מה שה-role שלו מתיר.' } }
      ]
    },
    {
      id: 'm07l6', minutes: 12,
      title: { en: 'Jargon and scenarios workout', he: 'אימון ז׳רגון ותרחישים' },
      blocks: [
        { t: 'p', en: 'Time to use it all together. First the words, then real situations, then the questions an interviewer asks about Runtime, and at the end you create a runtime in the console.', he: 'הגיע הזמן להשתמש בהכול יחד. קודם המילים, אחר כך מצבים אמיתיים, אחר כך השאלות שמראיין שואל על Runtime, ובסוף תיצור runtime בקונסול.' },
        { t: 'match', prompt: { en: 'Match the word to its meaning.', he: 'התאם את המילה למשמעות שלה.' }, pairs: [
          { a: 'Entrypoint', b: { en: 'The function behind POST /invocations', he: 'הפונקציה שמאחורי POST /invocations' } },
          { a: 'Qualifier', b: { en: 'The endpoint name you pass when invoking', he: 'שם ה-endpoint שמעבירים בזמן ההפעלה' } },
          { a: 'Execution role', b: { en: 'What the agent itself may do in AWS', he: 'מה הסוכן עצמו רשאי לעשות ב-AWS' } },
          { a: 'Control plane', b: { en: 'bedrock-agentcore-control: create and configure', he: 'bedrock-agentcore-control: יצירה והגדרה' } },
          { a: 'Data plane', b: { en: 'bedrock-agentcore: invoke at run time', he: 'bedrock-agentcore: הפעלה בזמן ריצה' } },
          { a: 'HealthyBusy', b: { en: 'Still working in the background, keep me alive', he: 'עדיין עובד ברקע, תשאיר אותי חי' } }
        ] },
        { t: 'match', prompt: { en: 'Match the number to what it limits.', he: 'התאם את המספר למה שהוא מגביל.' }, pairs: [
          { a: { en: '15 minutes', he: '15 דקות' }, b: { en: 'Default idle timeout, and one synchronous request', he: 'idle timeout ברירת מחדל, ובקשה סינכרונית אחת' } },
          { a: { en: '60 minutes', he: '60 דקות' }, b: { en: 'One streaming response', he: 'תשובת streaming אחת' } },
          { a: { en: '8 hours', he: '8 שעות' }, b: { en: 'Max lifetime of a session on microVMs', he: 'Max lifetime של session על microVMs' } },
          { a: { en: '33 characters', he: '33 תווים' }, b: { en: 'Minimum length of a session ID', he: 'אורך מינימלי של session ID' } },
          { a: { en: '250 MB', he: '250 MB' }, b: { en: 'Zipped size limit of a direct code package', he: 'גבול הגודל המכווץ של חבילת direct code' } },
          { a: { en: '8080', he: '8080' }, b: { en: 'Port of the HTTP protocol', he: 'הפורט של פרוטוקול HTTP' } }
        ] },
        { t: 'quiz', q: { en: 'The first message of every new conversation takes several seconds longer than the next ones. The agent imports heavy libraries at start. Which Runtime option is made for this?', he: 'ההודעה הראשונה של כל שיחה חדשה לוקחת כמה שניות יותר מההודעות הבאות. הסוכן מייבא ספריות כבדות בעלייה. איזו אפשרות של Runtime נועדה לזה?' },
          options: { en: ['Platform version V2: sessions start from a snapshot of the initialized environment', 'A longer idle timeout for all sessions', 'JWT inbound auth', 'A second endpoint'], he: ['Platform version V2: sessions עולים מתוך snapshot של הסביבה המאותחלת', 'idle timeout ארוך יותר לכל ה-sessions', 'JWT inbound auth', 'endpoint שני'] },
          answer: 0, explain: { en: 'This is a cold start problem: every new session pays the start time. V2 restores a snapshot taken after initialization, which gives fast and consistent cold starts. A longer idle timeout only helps users who come back, and it costs memory.', he: 'זו בעיית cold start: כל session חדש משלם את זמן העלייה. V2 משחזר snapshot שצולם אחרי האתחול, וזה נותן cold starts מהירים ועקביים. idle timeout ארוך יותר עוזר רק למשתמשים שחוזרים, והוא עולה זיכרון.' } },
        { t: 'quiz', q: { en: 'The cost report shows that most sessions stay alive 15 minutes after the user closed the chat window. How do you reduce that cost?', he: 'דוח העלויות מראה שרוב ה-sessions נשארים חיים 15 דקות אחרי שהמשתמש סגר את חלון הצ׳אט. איך מקטינים את העלות הזו?' },
          options: { en: ['Move to the Instances compute type', 'Call `StopRuntimeSession` when the conversation ends, and consider a shorter idle timeout', 'Use a larger container image', 'Send bigger payloads'], he: ['לעבור ל-compute מסוג Instances', 'לקרוא ל-`StopRuntimeSession` כשהשיחה נגמרת, ולשקול idle timeout קצר יותר', 'להשתמש ב-container image גדול יותר', 'לשלוח payloads גדולים יותר'] },
          answer: 1, explain: { en: 'Memory is billed while the session lives. If your app knows that the conversation is over, end the session at once. A shorter idle timeout covers the cases where the app does not know.', he: 'זיכרון מחויב כל עוד ה-session חי. אם האפליקציה שלך יודעת שהשיחה נגמרה, מסיימים את ה-session מיד. idle timeout קצר יותר מכסה את המקרים שבהם האפליקציה לא יודעת.' } },
        { t: 'quiz', q: { en: 'A blog post from 2025 tells you to run `agentcore configure -e my_agent.py` and then `agentcore launch`. What do you do?', he: 'פוסט מ-2025 אומר לך להריץ `agentcore configure -e my_agent.py` ואחר כך `agentcore launch`. מה אתה עושה?' },
          options: { en: ['Run them: they are the fastest way to deploy', 'Install the starter toolkit first, then run them', 'Recognize the deprecated starter toolkit, and use the current CLI instead: `agentcore create`, `agentcore dev`, `agentcore deploy`', 'Run them with `--legacy`'], he: ['להריץ אותן: זו הדרך המהירה ביותר לעשות deploy', 'קודם להתקין את ה-starter toolkit, ואז להריץ אותן', 'לזהות את ה-starter toolkit שהוצא משימוש, ולהשתמש במקומו ב-CLI הנוכחי: `agentcore create`, `agentcore dev`, `agentcore deploy`', 'להריץ אותן עם `--legacy`'] },
          answer: 2, explain: { en: '`configure` and `launch` belong to the old Python starter toolkit, which is no longer supported. The agent code in such posts (the `BedrockAgentCoreApp` wrapper) is still valid; only the deploy commands changed.', he: '`configure` ו-`launch` שייכות ל-starter toolkit הישן ב-Python, שכבר לא נתמך. קוד הסוכן בפוסטים כאלה (העטיפה של `BedrockAgentCoreApp`) עדיין תקף; רק פקודות ה-deploy השתנו.' } },
        { t: 'quiz', q: { en: 'A mobile app lets employees sign in with the company identity provider. The app should call the agent directly, in the name of the signed-in user. How do you set up the runtime?', he: 'אפליקציית מובייל מאפשרת לעובדים להזדהות דרך ספק הזהויות של החברה. האפליקציה צריכה לקרוא לסוכן ישירות, בשם המשתמש שהזדהה. איך מגדירים את ה-runtime?' },
          options: { en: ['SigV4, and ship IAM access keys inside the app', 'No inbound auth, and check the user inside the entrypoint', 'SigV4 and JWT together', 'JWT inbound auth with the discovery URL of the identity provider; the app sends the token of the user as a bearer token over HTTPS'], he: ['SigV4, ולשים IAM access keys בתוך האפליקציה', 'בלי inbound auth, ולבדוק את המשתמש בתוך ה-entrypoint', 'SigV4 ו-JWT יחד', 'JWT inbound auth עם ה-discovery URL של ספק הזהויות; האפליקציה שולחת את הטוקן של המשתמש כ-bearer token ב-HTTPS'] },
          answer: 3, explain: { en: 'Signed-in users have tokens, not IAM credentials, and access keys must never be shipped inside an app. A runtime uses SigV4 or JWT, not both. The other common design is: the app calls your backend, and the backend calls the agent with SigV4.', he: 'למשתמשים שהזדהו יש טוקנים, לא IAM credentials, ואסור לעולם לשים access keys בתוך אפליקציה. runtime משתמש ב-SigV4 או ב-JWT, לא בשניהם. התכנון הנפוץ האחר הוא: האפליקציה קוראת ל-backend שלך, וה-backend קורא לסוכן עם SigV4.' } },
        { t: 'reveal', q: { en: 'Interview question: "Walk me through what happens, end to end, when a user sends a message to an agent on AgentCore Runtime."', he: 'שאלת ראיון: "תאר לי מה קורה, מקצה לקצה, כשמשתמש שולח הודעה לסוכן ב-AgentCore Runtime."' },
          a: { en: 'The app calls InvokeAgentRuntime on the data plane with the runtime ARN, an endpoint qualifier, a session ID and a payload. Runtime first checks inbound auth: a SigV4 signature or a JWT. Then it resolves the endpoint to a version, and looks at the session ID. For a new ID it starts a dedicated microVM with my code; for a known ID it routes to the microVM that is already running. It sends the payload to POST /invocations on port 8080, and my entrypoint runs the agent loop: model calls and tool calls, made with the execution role. The answer goes back as JSON or as an SSE stream. Afterwards the session is idle; after 15 idle minutes, or 8 hours in total, the microVM is destroyed. Logs, metrics and traces of all this go to CloudWatch.', he: 'האפליקציה קוראת ל-InvokeAgentRuntime ב-data plane עם ה-ARN של ה-runtime, qualifier של endpoint, session ID ו-payload. Runtime בודק קודם את ה-inbound auth: חתימת SigV4 או JWT. אחר כך הוא ממפה את ה-endpoint ל-version, ומסתכל על ה-session ID. ל-ID חדש הוא מעלה microVM ייעודי עם הקוד שלי; ל-ID מוכר הוא מנתב ל-microVM שכבר רץ. הוא שולח את ה-payload ל-POST /invocations על פורט 8080, וה-entrypoint שלי מריץ את לולאת הסוכן: קריאות למודל וקריאות לכלים, שנעשות עם ה-execution role. התשובה חוזרת כ-JSON או כ-stream של SSE. אחר כך ה-session במצב idle; אחרי 15 דקות idle, או 8 שעות בסך הכול, ה-microVM מושמד. הלוגים, ה-metrics וה-traces של כל זה הולכים ל-CloudWatch.' } },
        { t: 'reveal', q: { en: 'Interview question: "Users say the agent forgets the conversation after a break. How do you investigate, and what are the possible fixes?"', he: 'שאלת ראיון: "משתמשים אומרים שהסוכן שוכח את השיחה אחרי הפסקה. איך אתה חוקר, ומה התיקונים האפשריים?"' },
          a: { en: 'First I check two things. Does the app send the same runtimeSessionId on every turn? If it creates a new ID per message, every message is a new session. Second, how long was the break? With the default idle timeout of 15 minutes, a longer break terminates the session, and the same ID gets a fresh microVM with no history. The fixes: reuse the session ID correctly; raise idleRuntimeSessionTimeout if longer breaks are normal, knowing that I pay for memory while sessions live; and, the real fix, stop relying on process memory. I store the conversation in AgentCore Memory or a database and load it when a session starts, so the agent survives any restart, timeout or deploy.', he: 'קודם אני בודק שני דברים. האם האפליקציה שולחת את אותו runtimeSessionId בכל תור? אם היא יוצרת ID חדש לכל הודעה, כל הודעה היא session חדש. שנית, כמה זמן נמשכה ההפסקה? עם idle timeout ברירת מחדל של 15 דקות, הפסקה ארוכה יותר מסיימת את ה-session, ואותו ID מקבל microVM חדש בלי היסטוריה. התיקונים: להשתמש נכון באותו session ID; להעלות את idleRuntimeSessionTimeout אם הפסקות ארוכות הן דבר רגיל, בידיעה שמשלמים על זיכרון כל עוד sessions חיים; והתיקון האמיתי, להפסיק להסתמך על הזיכרון של התהליך. אני שומר את השיחה ב-AgentCore Memory או במסד נתונים וטוען אותה כש-session מתחיל, כך שהסוכן שורד כל הפעלה מחדש, timeout או deploy.' } },
        { t: 'reveal', q: { en: 'Interview question: "Container or direct code deployment for our agent? How do you decide?"', he: 'שאלת ראיון: "Container או direct code deployment לסוכן שלנו? איך אתה מחליט?"' },
          a: { en: 'I start with direct code deployment. It is a ZIP of code and dependencies, it needs no Docker, deploys are fast, and AWS patches the language runtime, so there is less for us to maintain. I move to a container when I hit one of three things: the package is over 250 MB zipped, I need system-level dependencies or a language that is not Python or Node.js, or the company already has container pipelines and image scanning that we must use. With a container we own the base image and its security patches, and the image must be ARM64. In both cases the agent code and the contract are the same, so changing later is not a rewrite.', he: 'אני מתחיל עם direct code deployment. זה ZIP של קוד ותלויות, לא צריך Docker, ה-deploys מהירים, ו-AWS מעדכנת את ה-runtime של השפה, אז יש לנו פחות לתחזק. אני עובר ל-container כשאני נתקל באחד משלושה דברים: החבילה גדולה מ-250 MB מכווץ, צריך תלויות ברמת המערכת או שפה שהיא לא Python או Node.js, או שלחברה כבר יש pipelines של containers וסריקת images שחייבים להשתמש בהם. עם container ה-base image ועדכוני האבטחה שלו באחריותנו, וה-image חייב להיות ARM64. בשני המקרים קוד הסוכן והחוזה זהים, כך שמעבר מאוחר יותר הוא לא כתיבה מחדש.' } },
        { t: 'h', en: 'Console lab: create a runtime', he: 'מעבדת קונסול: יוצרים runtime' },
        { t: 'console', service: 'Amazon Bedrock AgentCore', nav: ['Agents', '#Resources', 'Gateways', 'Observability'], active: 'Agents',
          crumbs: ['Amazon Bedrock AgentCore', 'Agents', 'Create Host agent (runtime)'],
          task: { en: 'Host the support agent from the console. Name it `support_agent`. The code is a container image: `111122223333.dkr.ecr.us-west-2.amazonaws.com/support-agent:latest`. The agent imports heavy libraries, so you want fast and consistent cold starts. The callers are employees who sign in with the company identity provider (discovery URL `https://idp.example.com/.well-known/openid-configuration`, client `support-web`). The agent must reach a private database in your network. It runs with the IAM role `AgentExecutionRole`.', he: 'ארח את סוכן התמיכה מהקונסול. קרא לו `support_agent`. הקוד הוא container image: `111122223333.dkr.ecr.us-west-2.amazonaws.com/support-agent:latest`. הסוכן מייבא ספריות כבדות, אז אתה רוצה cold starts מהירים ועקביים. הקוראים הם עובדים שמזדהים דרך ספק הזהויות של החברה (discovery URL: `https://idp.example.com/.well-known/openid-configuration`, client: `support-web`). הסוכן חייב להגיע למסד נתונים פרטי ברשת שלך. הוא רץ עם ה-IAM role בשם `AgentExecutionRole`.' },
          steps: [
            { heading: 'Agent details', panels: [ { title: 'Agent details', fields: [
              { label: 'Name', type: 'input', value: '', n: 1, expect: 'support_agent', hint: { en: 'The name is given in the task.', he: 'השם נתון במשימה.' } },
              { label: 'Compute type', type: 'radio', options: ['microVMs', 'Instances'], value: 'microVMs', n: 2 },
              { label: 'Agent/tool source', type: 'input', value: '', placeholder: 'Container image URI', n: 3, expect: '111122223333.dkr.ecr.us-west-2.amazonaws.com/support-agent:latest', hint: { en: 'Paste the image URI from the task.', he: 'הדבק את ה-URI של ה-image מהמשימה.' } },
              { label: 'Platform version', type: 'radio', options: ['V1', 'V2'], value: 'V1', n: 4, expect: 'V2', hint: { en: 'Which platform version starts sessions from a snapshot?', he: 'איזו platform version מעלה sessions מתוך snapshot?' } } ] } ] },
            { heading: 'Inbound auth', panels: [ { title: 'Inbound auth', n: 5, fields: [
              { label: 'Inbound auth', type: 'radio', options: ['IAM SigV4', 'JWT bearer token'], value: 'IAM SigV4', expect: 'JWT bearer token', hint: { en: 'The callers are signed-in users with tokens, not AWS identities.', he: 'הקוראים הם משתמשים שהזדהו ויש להם טוקנים, לא זהויות של AWS.' } },
              { label: 'Discovery URL', type: 'input', value: '', expect: 'https://idp.example.com/.well-known/openid-configuration', hint: { en: 'Copy it from the task.', he: 'העתק אותו מהמשימה.' } },
              { label: 'Allowed clients', type: 'input', value: '', expect: 'support-web', hint: { en: 'The client ID of the app that may call.', he: 'ה-client ID של האפליקציה שרשאית לקרוא.' } } ] } ] },
            { heading: 'Permissions and network', panels: [ { title: 'Permissions', n: 6, fields: [
              { label: 'IAM execution role', type: 'input', value: '', expect: ['AgentExecutionRole', '/^arn:aws:iam::\\d{12}:role\\/AgentExecutionRole$/'], hint: { en: 'The role name from the task.', he: 'שם ה-role מהמשימה.' } } ] },
              { title: 'Advanced configurations', n: 7, fields: [
              { label: 'VPC', type: 'toggle', value: false, expect: true, hint: { en: 'The agent must reach a private database.', he: 'הסוכן חייב להגיע למסד נתונים פרטי.' } } ] } ] }
          ],
          primary: 'Create runtime',
          callouts: [
            { n: 1, en: 'The name becomes part of the ARN: runtime/<name>-<suffix>.', he: 'השם הופך לחלק מה-ARN: runtime/<name>-<suffix>.' },
            { n: 2, en: 'microVMs is the default and fits almost every agent. Instances is for GPUs or sessions longer than 8 hours.', he: 'microVMs היא ברירת המחדל ומתאימה כמעט לכל סוכן. Instances מיועד ל-GPUs או ל-sessions ארוכים מ-8 שעות.' },
            { n: 3, en: 'A container image in ECR (built for ARM64), or a code package.', he: 'container image ב-ECR (שנבנה ל-ARM64), או חבילת קוד.' },
            { n: 4, en: 'V2 restores a snapshot of the initialized environment: faster, more consistent cold starts.', he: 'V2 משחזר snapshot של הסביבה המאותחלת: cold starts מהירים ועקביים יותר.' },
            { n: 5, en: 'One method per runtime. With JWT, callers use plain HTTPS and not the AWS SDK.', he: 'שיטה אחת לכל runtime. עם JWT, הקוראים משתמשים ב-HTTPS רגיל ולא ב-SDK של AWS.' },
            { n: 6, en: 'What the agent itself may do in AWS. Keep it small.', he: 'מה הסוכן עצמו רשאי לעשות ב-AWS. שומרים עליו קטן.' },
            { n: 7, en: 'In a VPC you choose subnets and security groups. Remember: private subnets, a NAT gateway and VPC endpoints.', he: 'ב-VPC בוחרים subnets ו-security groups. לזכור: private subnets, NAT gateway ו-VPC endpoints.' } ],
          success: { en: 'Runtime created. The DEFAULT endpoint now points to version 1. For production traffic, add a named endpoint.', he: 'ה-runtime נוצר. ה-endpoint בשם DEFAULT מצביע עכשיו על version 1. לתעבורת פרודקשן, מוסיפים endpoint עם שם.' },
          caption: { en: 'Simplified. The field names are the ones the AWS docs mention for this screen (November 2026). The full form was not available, so the layout, the option names under "Inbound auth" and the VPC switch are an illustration.', he: 'מפושט. שמות השדות הם אלה שהתיעוד של AWS מזכיר למסך הזה (נובמבר 2026). הטופס המלא לא היה זמין, ולכן הפריסה, שמות האפשרויות תחת "Inbound auth" ומתג ה-VPC הם המחשה.' } },
        { t: 'task', title: { en: 'Do it for real (after you land)', he: 'עשה את זה באמת (אחרי הנחיתה)' }, steps: {
          en: ['Install the CLI: `npm install -g @aws/agentcore`, then check `agentcore --version`.', 'Run `agentcore create --name MyProject --template agent-python-strands` and read `app/agent/main.py`. Find the entrypoint.', 'Run `agentcore dev --mode browser` and talk to the agent in the Agent Inspector.', 'Run `agentcore deploy`, then `agentcore status --json`, and copy the runtime ARN.', 'Write a ten-line Python script that calls `invoke_agent_runtime` twice with the same UUID session ID. Check that the second answer knows the first question.', 'Wait more than 15 minutes and call again with the same session ID. See that the context is gone. This is the lesson you will not forget.', 'Look at `agentcore logs runtime --since 30m` and `agentcore traces runtime list --since 30m`.', 'Clean up: `agentcore remove all --yes && agentcore deploy --yes`.'],
          he: ['התקן את ה-CLI: `npm install -g @aws/agentcore`, ואז בדוק `agentcore --version`.', 'הרץ `agentcore create --name MyProject --template agent-python-strands` וקרא את `app/agent/main.py`. מצא את ה-entrypoint.', 'הרץ `agentcore dev --mode browser` ודבר עם הסוכן ב-Agent Inspector.', 'הרץ `agentcore deploy`, אחר כך `agentcore status --json`, והעתק את ה-ARN של ה-runtime.', 'כתוב סקריפט Python של עשר שורות שקורא ל-`invoke_agent_runtime` פעמיים עם אותו session ID מסוג UUID. בדוק שהתשובה השנייה מכירה את השאלה הראשונה.', 'חכה יותר מ-15 דקות וקרא שוב עם אותו session ID. ראה שההקשר נעלם. זה השיעור שלא תשכח.', 'הסתכל על `agentcore logs runtime --since 30m` ועל `agentcore traces runtime list --since 30m`.', 'נקה: `agentcore remove all --yes && agentcore deploy --yes`.'] } }
      ]
    }
  ]
});
